const s={"lng-en-gram":[["Present simple","Habitudes et vérités générales : I work, he works (+s à la 3ᵉ personne)."],["Present continuous","Action en cours : be + V-ing (I am working)."],["Preterit","Passé daté et révolu : V-ed ou forme irrégulière (I worked, I went)."],["Present perfect","Lien passé-présent : have + participe passé (I have worked)."],["Auxiliaire","Verbe outil (be, have, do) servant à conjuguer, nier, interroger."],["Modal","Verbe (can, must, should…) exprimant capacité, obligation, conseil."]],"lng-en-voc":[["Faux-ami","Mot ressemblant au français mais de sens différent (actually = en fait)."],["Phrasal verb","Verbe + particule au sens global (give up = abandonner)."],["Collocation","Association habituelle de mots (make a decision, do homework)."],["Registre","Niveau de langue (formal / informal) adapté à la situation."],["Connecteur logique","Mot de liaison (however, therefore, moreover) structurant le discours."],["Synonyme","Mot de sens proche permettant d’enrichir et de varier l’expression."]],"lng-en-verbs":[["Verbe irrégulier","Verbe dont le preterit et le participe passé ne suivent pas la règle en -ed."],["Base verbale","Forme du verbe sans terminaison (go, take)."],["Preterit","2ᵉ colonne (went, took) : passé simple révolu."],["Participe passé","3ᵉ colonne (gone, taken) : utilisé avec have et au passif."],["Present perfect","have + participe passé, pour un lien avec le présent."]],"lng-en-grammar-ex":[["Question tag","Petite question en fin de phrase (…, isn’t it ?)."],["Comparatif","Comparaison : -er than / more … than."],["Superlatif","Le plus … : the -est / the most …."],["Voix passive","Sujet subissant l’action : be + participe passé."],["Discours indirect","Rapporter des propos (He said that…), avec recul des temps."]],"lng-en-comp":[["Skimming","Lecture rapide pour saisir l’idée générale d’un texte."],["Scanning","Lecture ciblée pour repérer une information précise."],["Main idea","Idée principale d’un paragraphe ou d’un document."],["Inférer","Déduire une information implicite à partir du contexte."],["Paraphraser","Reformuler une idée avec ses propres mots."]],"lng-es-gram":[["Ser / Estar","Deux verbes « être » : ser (identité durable) / estar (état, lieu)."],["Presente","Présent de l’indicatif : hablo, como, vivo."],["Pretérito perfecto","Passé lié au présent : he hablado (haber + participe)."],["Pretérito indefinido","Passé simple révolu : hablé, comí."],["Gerundio","Forme en -ando/-iendo exprimant l’action en cours (estoy hablando)."],["Subjuntivo","Mode du souhait, du doute, de l’ordre (que hables)."]],"lng-es-voc":[["Falso amigo","Mot trompeur (embarazada = enceinte, pas embarrassée)."],["Ser vs Estar","Choix du bon « être » selon caractère durable ou passager."],["Género","Genre du nom (el / la) déterminant les accords."],["Conector","Mot de liaison (sin embargo, por lo tanto) organisant le discours."],["Registro","Niveau de langue (tú familier / usted formel)."],["Sinónimo","Mot de sens proche pour varier le vocabulaire."]],"lng-es-verbs":[["Verbo irregular","Verbe dont le radical change à la conjugaison (tener → tengo)."],["Diptongación","Voyelle du radical devenant diphtongue (poder → puedo)."],["Participio","Participe passé (hablado, hecho) utilisé avec haber."],["Gerundio","Forme en -ando/-iendo pour l’action en cours."],["Pretérito indefinido","Passé simple, souvent irrégulier (hice, fui)."]],"lng-es-grammar-ex":[["Concordancia","Accord en genre et en nombre entre noms, adjectifs et articles."],["Comparativo","Comparaison : más … que / menos … que."],["Superlativo","Le plus … : el más … ; superlatif absolu en -ísimo."],["Voz pasiva","ser + participe (fue construido) ou passive avec se."],["Estilo indirecto","Rapporter des propos (dijo que…), avec changement des temps."]],"lng-es-comp":[["Idea principal","Idée centrale d’un texte ou d’un paragraphe."],["Inferir","Déduire une information implicite du contexte."],["Palabra clave","Mot porteur du sens, utile au repérage."],["Parafrasear","Reformuler une idée avec ses propres mots."],["Cognado","Mot transparent, proche du français (información)."]],"lng-it-gram":[["il libro","Le livre ; pluriel i libri."],["lo studente","L’élève ; pluriel gli studenti."],["è","Est, forme de essere, avec accent."],["e","Et, conjonction sans accent."],["Essere","Être : sono, sei, è, siamo, siete, sono."],["Avere","Avoir : ho, hai, ha, abbiamo, avete, hanno."],["Non","Négation placée avant le verbe."],["Capire","Comprendre : capisco, capiamo."],["Passato prossimo","Auxiliaire au présent + participe passé pour présenter un événement accompli."],["Imperfetto","Temps des habitudes, descriptions et arrière-plans du passé."]],"lng-ar-gram":[["Fatḥa","Signe de la voyelle brève a : ـَ."],["Shadda","Signe de redoublement de la consonne : ـّ."],["مرحبا","Bonjour ; translittération indicative marḥaban."],["اسمي","Mon nom est / je m’appelle : ismī."],["ال","Article défini attaché au nom."],["الكتاب الجديد","Le livre nouveau : adjectif épithète également défini."],["الكتاب جديد","Le livre est nouveau : phrase nominale."],["كتابي","Mon livre : suffixe possessif ـي."],["Accompli","Forme présentant notamment un procès accompli : كَتَبَ, il a écrit."],["Inaccompli","Forme servant notamment au présent : يَكْتُبُ, il écrit."]],"lng-it-voc":[["Tirocinio","Stage en milieu professionnel."],["Biglietto","Billet, notamment de transport."],["Cordiali saluti","Formule de clôture d’un message professionnel."],["Fatturato","Chiffre d’affaires, distinct du bénéfice."],["Utile","Bénéfice."],["Dipendente","Salarié."],["Fattura","Facture."],["Dati personali","Données personnelles."],["Fonte","Source d’une information."],["Rifiuti","Déchets."]],"lng-ar-voc":[["الجامعة","L’université."],["المحطة","La gare / la station."],["التذكرة","Le billet."],["من فضلك","S’il te plaît / s’il vous plaît, selon le destinataire."],["الشركة","L’entreprise."],["العميل","Le client."],["التكلفة","Le coût."],["الربح","Le bénéfice."],["المصدر","La source."],["البيانات الشخصية","Les données personnelles."]],"lng-it-comp":[["Libreria","Librairie, et non bibliothèque."],["Consenso","Consentement."],["Vorrei","Je voudrais : projet souhaité."],["Riparazione","Réparation."],["Mentre","Tandis que ; met ici deux positions en contraste."],["Non ancora","Pas encore."]],"lng-ar-comp":[["الزبائن","Les clients."],["موافقتهم","Leur accord / consentement."],["في الصيف الماضي","L’été dernier."],["ورشة","Atelier."],["الضجيج","Bruit."],["لم… بعد","Négation correspondant ici à pas encore."]],"lng-it-culture-terminale":[["piazza","Place publique."],["spazio condiviso","Espace partagé."],["commercio","Commerce."],["memoria","Mémoire."],["targa","Plaque, notamment commémorative."],["commemorazione","Commémoration."],["punto di vista","Point de vue."],["personaggio","Personnage."],["montaggio","Montage cinématographique."],["fonte","Source."]],"lng-ar-culture-terminale":[["الفضاء العام","L’espace public."],["الحياة الخاصة","La vie privée."],["النشر","La publication / la diffusion."],["الذاكرة","La mémoire."],["الشهادة","Le témoignage, dans le contexte de cette fiche."],["الأرشيف","Les archives."],["الرواية","Le roman."],["الشخصية","Le personnage, dans un récit."],["الخيال","L’imagination / la fiction."],["الجمهور","Le public."]]},p=Object.freeze(Object.defineProperty({__proto__:null,default:s},Symbol.toStringTag,{value:"Module"})),l={"lng-en-gram":{resources:[{label:"Lingolia English — grammaire (règles + exercices)",url:"https://english.lingolia.com/en/grammar",kind:"link"},{label:"BBC Learning English",url:"https://www.bbc.co.uk/learningenglish",kind:"video"}]},"lng-en-voc":{resources:[{label:"BBC Learning English — vocabulary",url:"https://www.bbc.co.uk/learningenglish",kind:"video"}]},"lng-en-verbs":{resources:[{label:"Lingolia — irregular verbs (liste + exercices)",url:"https://english.lingolia.com/en/grammar/verbs/irregular-verbs",kind:"link"}]},"lng-en-grammar-ex":{resources:[{label:"Lingolia English — exercices de grammaire",url:"https://english.lingolia.com/en/grammar",kind:"link"}]},"lng-en-comp":{resources:[{label:"BBC Learning English — 6 Minute English",url:"https://www.bbc.co.uk/learningenglish",kind:"video",note:"S’entraîner à comprendre un texte / un audio."}],sections:[{h:"📖 Méthode — comprendre un texte en anglais",blocks:[{t:"list",c:["**Repère d’abord** le titre, la source et la date : ils donnent le thème.","**Ne bloque pas sur chaque mot** : devine le sens grâce au contexte et aux mots transparents (information, situation…).","**Cherche les mots-clés** (qui ? quoi ? où ? quand ? pourquoi ?) et les connecteurs (but, because, however, so).","**Reformule** chaque paragraphe en une phrase, en français puis en anglais."]},{t:"tip",h:"ETLV / STMG",c:"Le dictionnaire intégré 📖 traduit aussi les phrases : sers-t’en pour vérifier, pas pour tout traduire mot à mot."}]}]},"lng-es-gram":{resources:[{label:"Lingolia Español — gramática (reglas + ejercicios)",url:"https://espanol.lingolia.com/es/gramatica",kind:"link"}]},"lng-es-voc":{resources:[{label:"Lingolia Español — vocabulario",url:"https://espanol.lingolia.com/es/vocabulario",kind:"link"}]},"lng-es-verbs":{resources:[{label:"Lingolia — verbos irregulares (conjugación)",url:"https://espanol.lingolia.com/es/gramatica/verbos",kind:"link"}]},"lng-es-grammar-ex":{resources:[{label:"Lingolia Español — ejercicios",url:"https://espanol.lingolia.com/es/gramatica",kind:"link"}]},"lng-es-comp":{resources:[{label:"Lingolia Español — comprensión & gramática",url:"https://espanol.lingolia.com/es",kind:"link"}],sections:[{h:"📖 Méthode — comprendre un texte en espagnol",blocks:[{t:"list",c:["**Repère** le titre, la source, la date → le thème.","**Appuie-toi sur les mots transparents** (información, situación, economía) et le contexte.","**Attention aux faux-amis** (ex. « éxito » = succès, pas sortie) et aux connecteurs (pero, porque, sin embargo).","**Reformule** chaque paragraphe en une phrase simple."]},{t:"tip",h:"Astuce",c:"Les terminaisons des verbes indiquent la personne et le temps : identifie-les pour comprendre qui fait quoi et quand."}]}]},"lng-it-gram":{resources:[{label:"Programme officiel de italien — lycée général et technologique",url:"https://www.education.gouv.fr/sites/default/files/annexe-14-programme-d-italien-pour-les-classes-de-lyc-e-g-n-ral-et-technologique-440388.pdf",kind:"link"}]},"lng-ar-gram":{resources:[{label:"Programme officiel de arabe — lycée général et technologique",url:"https://www.education.gouv.fr/sites/default/files/annexe-6-programme-d-arabe-pour-les-classes-de-lyc-e-g-n-ral-et-technologique-440367.pdf",kind:"link"}]},"lng-it-voc":{resources:[{label:"Programme officiel de italien — lycée général et technologique",url:"https://www.education.gouv.fr/sites/default/files/annexe-14-programme-d-italien-pour-les-classes-de-lyc-e-g-n-ral-et-technologique-440388.pdf",kind:"link"}]},"lng-ar-voc":{resources:[{label:"Programme officiel de arabe — lycée général et technologique",url:"https://www.education.gouv.fr/sites/default/files/annexe-6-programme-d-arabe-pour-les-classes-de-lyc-e-g-n-ral-et-technologique-440367.pdf",kind:"link"}]},"lng-it-comp":{resources:[{label:"Programme officiel de italien — lycée général et technologique",url:"https://www.education.gouv.fr/sites/default/files/annexe-14-programme-d-italien-pour-les-classes-de-lyc-e-g-n-ral-et-technologique-440388.pdf",kind:"link"}]},"lng-ar-comp":{resources:[{label:"Programme officiel de arabe — lycée général et technologique",url:"https://www.education.gouv.fr/sites/default/files/annexe-6-programme-d-arabe-pour-les-classes-de-lyc-e-g-n-ral-et-technologique-440367.pdf",kind:"link"}]},"lng-it-culture-terminale":{resources:[{label:"Programme officiel de italien — lycée général et technologique",url:"https://www.education.gouv.fr/sites/default/files/annexe-14-programme-d-italien-pour-les-classes-de-lyc-e-g-n-ral-et-technologique-440388.pdf",kind:"link"}]},"lng-ar-culture-terminale":{resources:[{label:"Programme officiel de arabe — lycée général et technologique",url:"https://www.education.gouv.fr/sites/default/files/annexe-6-programme-d-arabe-pour-les-classes-de-lyc-e-g-n-ral-et-technologique-440367.pdf",kind:"link"}]}},d=Object.freeze(Object.defineProperty({__proto__:null,default:l},Symbol.toStringTag,{value:"Module"})),u={"cmp-en-a2-read":0,"cmp-en-a2-listen":0,"cmp-en-b1-read":1,"cmp-en-b1-listen":1,"cmp-en-b2-read":2,"cmp-en-b2-listen":2,"cmp-es-a2-read":0,"cmp-es-a2-listen":0,"cmp-es-b1-read":1,"cmp-es-b1-listen":1,"cmp-es-b2-read":2,"cmp-es-b2-listen":2,"lng-en-present-trou":0,"lng-en-past-qcm":1,"lng-en-future-trou":2,"lng-en-modal-qcm":3,"lng-en-cond-trou":4,"lng-en-irr-memory":5,"lng-en-irr-trou":5,"lng-en-voc-daily-memory":0,"lng-en-voc-biz-qcm":2,"lng-en-voc-env-assoc":4,"lng-en-voc-phrasal-qcm":6,"lng-es-serestar-tri":0,"lng-es-presente-trou":0,"lng-es-pasado-tri":1,"lng-es-perfecto-trou":2,"lng-es-futuro-trou":3,"lng-es-subj-qcm":4,"lng-es-gustar-qcm":5,"lng-es-irr-memory":6,"lng-es-voc-daily-memory":0,"lng-es-voc-empresa-qcm":2,"lng-es-voc-medio-assoc":4,"lng-es-voc-verbos-memory":6,"lng-en-verbs-gen":0,"lng-es-verbs-gen":0,"lng-en-grammar-gen":0,"lng-es-grammar-gen":0,"lng-it-gram-s1-qcm":0,"lng-it-gram-s2-qcm":1,"lng-it-gram-s3-qcm":2,"lng-it-gram-s4-qcm":3,"lng-it-gram-s5-qcm":4,"lng-it-gram-s6-qcm":5,"lng-ar-gram-s1-qcm":0,"lng-ar-gram-s2-qcm":1,"lng-ar-gram-s3-qcm":2,"lng-ar-gram-s4-qcm":3,"lng-ar-gram-s5-qcm":4,"lng-ar-gram-s6-qcm":5,"lng-it-voc-s1-qcm":0,"lng-it-voc-s2-qcm":1,"lng-it-voc-s3-qcm":2,"lng-ar-voc-s1-qcm":0,"lng-ar-voc-s2-qcm":1,"lng-ar-voc-s3-qcm":2,"lng-it-comp-s1-qcm":0,"lng-it-comp-s2-qcm":1,"lng-ar-comp-s1-qcm":0,"lng-ar-comp-s2-qcm":1,"lng-it-culture-terminale-s1-qcm":0,"lng-it-culture-terminale-s2-qcm":1,"lng-it-culture-terminale-s3-qcm":2,"lng-it-culture-terminale-s4-qcm":3,"lng-it-culture-terminale-s5-qcm":4,"lng-it-culture-terminale-s6-qcm":5,"lng-ar-culture-terminale-s1-qcm":0,"lng-ar-culture-terminale-s2-qcm":1,"lng-ar-culture-terminale-s3-qcm":2,"lng-ar-culture-terminale-s4-qcm":3,"lng-ar-culture-terminale-s5-qcm":4,"lng-ar-culture-terminale-s6-qcm":5},m=Object.freeze(Object.defineProperty({__proto__:null,default:u},Symbol.toStringTag,{value:"Module"})),e="langues",i="Langues (Anglais / Espagnol / Italien / Arabe)",a="Langues",n="🗣️",t="#db2777",r="Grammaire, vocabulaire, compréhension et cultures en quatre langues. Des applications STMG et ETLV.",o=[{id:"lng-en-gram",name:"Anglais — Toutes les conjugaisons",short:"Anglais · conjugaison",keywords:"present simple continuous preterit present perfect past perfect futur will going to modaux conditionnels passif verbes irréguliers anglais conjugaison temps",intro:"Tous les temps anglais, à consulter et à réviser : présent, passé, futur, modaux, conditionnels, voix passive et la liste des verbes irréguliers.",cours:[{h:"Le présent simple et le présent continu (be + V-ing)",blocks:[{t:"p",c:"Le **present simple** se forme avec la **base verbale**, à laquelle on ajoute un **-s à la troisième personne du singulier** : *She work**s** every day.* À la forme **négative**, on utilise l’auxiliaire **don’t**, ou **doesn’t** à la troisième personne, suivi de la base : *He does**n’t** work on Sundays.* Le -s passe alors sur l’auxiliaire, et le verbe reste à la base."},{t:"p",c:"À la forme **interrogative**, on place **Do** ou **Does** devant le sujet, puis la base verbale : *Do you work here?* On emploie le present simple pour parler des **habitudes** et des **vérités générales**, comme *Water boils at 100 °C.*"},{t:"p",c:"Le **present continuous** se forme avec l’auxiliaire **be** conjugué au présent (**am, is, are**) suivi du verbe en **-ing** : *They are work**ing** now.* À la forme **négative**, on ajoute **not** après l’auxiliaire : *I’m not working today.* À la forme **interrogative**, on place l’auxiliaire devant le sujet : *Are you listening?*"},{t:"p",c:"On l’emploie pour une **action en cours** au moment où l’on parle, ou pour une situation **temporaire** : *She is studying for her exam.*"},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Present simple (affirmative)","Sujet + base, avec -s à la 3ᵉ personne du singulier (She works)"],["Present simple (négative)","don’t / doesn’t + base (He doesn’t work)"],["Present simple (interrogative)","Do / Does + sujet + base ? (Do you work here?)"],["Emploi du present simple","Habitudes, vérités générales"],["Present continuous (affirmative)","am / is / are + V-ing (They are working)"],["Present continuous (négative)","am / is / are + not + V-ing"],["Present continuous (interrogative)","Am / Is / Are + sujet + V-ing ?"],["Emploi du present continuous","Action en cours, situation temporaire"]]}]},{h:"Le passé : prétérit ou present perfect",blocks:[{t:"p",c:"Le **prétérit** se forme en ajoutant **-ed** à la base des verbes réguliers, *We visit**ed** Rome*, ou en utilisant la forme propre des **verbes irréguliers**, *I **went** home.* À la forme **négative**, on emploie **didn’t** suivi de la **base** : *They did**n’t** come* — l’auxiliaire porte déjà la marque du passé. À la forme **interrogative**, on place **Did** devant le sujet : *Did you see it?*"},{t:"p",c:"On emploie le prétérit pour une **action passée, datée et terminée**, sans lien avec le présent : *She was born in 2007.*"},{t:"p",c:"Le **present perfect** se forme avec **have** ou **has** suivi du **participe passé** : *I have finish**ed**.* À la forme **négative**, on emploie **haven’t** ou **hasn’t** : *He has**n’t** arrived.* À la forme **interrogative**, on place **Have** ou **Has** devant le sujet : *Have you eaten?*"},{t:"p",c:"On l’emploie pour marquer un **lien entre le passé et le présent** : une action passée dont le résultat compte maintenant, ou une situation qui dure encore. Il s’accompagne souvent de **for**, **since**, **already**, **yet** ou **ever** : *I’ve known her **for** years.*"},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Prétérit (affirmative)","Base + -ed, ou forme irrégulière (We visited / I went)"],["Prétérit (négative)","didn’t + base"],["Prétérit (interrogative)","Did + sujet + base ?"],["Emploi du prétérit","Action passée, datée et terminée"],["Present perfect (affirmative)","have / has + participe passé"],["Present perfect (négative)","haven’t / hasn’t + participe passé"],["Present perfect (interrogative)","Have / Has + sujet + participe passé ?"],["Emploi du present perfect","Lien passé-présent (for, since, already, yet, ever)"]]}]},{h:"Le past perfect et le futur : will, be going to, be + V-ing",blocks:[{t:"p",c:"Le **past perfect** se forme avec **had** suivi du **participe passé** ; il sert à exprimer une action antérieure à une autre action passée : *She **had left** before I arrived.* Pour le futur, l’anglais dispose de plusieurs formes. **Will + base** exprime une prédiction ou une décision prise sur le moment : *I **will** call you*, *I’ll help.* **Be going to + base** exprime une intention ou une prévision fondée sur des indices : *It’s **going to** rain.*"},{t:"p",c:"**Be + V-ing**, le present continuous, exprime un **projet** déjà organisé : *I’m meeting him tomorrow.* Le **future perfect**, enfin, se forme avec **will have + participe passé** et décrit une action qui sera accomplie avant un moment futur : *By 2030, he **will have** graduated.*"},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Past perfect","had + participe passé (action antérieure à une autre action passée)"],["Futur avec will","will + base (prédiction, décision immédiate)"],["Futur avec be going to","am / is / are going to + base (intention, prévision)"],["Futur de projet","be + V-ing (I’m meeting him tomorrow)"],["Future perfect","will have + participe passé"]]}]},{h:"Les modaux : can, may, must, should, would + base verbale",blocks:[{t:"p",c:"Chaque modal a son sens. **Can** et **could** expriment la **capacité** ou la **possibilité** : *I **can** swim*, et *could* sert aussi à demander poliment, *Could you help?* **May** et **might** expriment la **probabilité**, *It **may** rain*, ou la **permission**, *You **may** go.* **Must** exprime une **obligation forte**, *You **must** stop*, ou une **quasi-certitude**, *He **must** be tired.*"},{t:"p",c:"**Have to** exprime une obligation qui vient de l’**extérieur** : *I **have to** work tomorrow.* **Should** et **ought to** expriment le **conseil** : *You **should** rest.* **Would**, enfin, exprime l’**hypothèse** ou la **politesse** : *I **would** like a coffee.*"},{t:"p",c:"**Règle** : un modal est toujours suivi de la **base verbale** (pas de « to », pas de « -s », pas de « -ed »)."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["can / could","Capacité, possibilité (demande polie avec could)"],["may / might","Probabilité, permission"],["must","Obligation forte, quasi-certitude"],["have to","Obligation extérieure"],["should / ought to","Conseil"],["would","Hypothèse, politesse"],["Modal + base verbale","Jamais de to, de -s ni de -ed après un modal"]]}]},{h:"Les conditionnels (if) et la voix passive (be + participe passé)",blocks:[{t:"p",c:"On distingue quatre types de phrases conditionnelles. Le **type 0** exprime une **vérité générale** : *if* + présent, puis présent — *If you heat ice, it melts.* Le **type 1** exprime une condition **réelle**, qui peut se réaliser : *if* + présent, puis **will** + base — *If it rains, we **will** stay.*"},{t:"p",c:"Le **type 2** exprime une condition **irréelle dans le présent** : *if* + prétérit, puis **would** + base — *If I **were** rich, I **would** travel.* Le **type 3** exprime une condition **irréelle dans le passé**, un regret : *if* + past perfect, puis **would have** + participe passé — *If I had known, I **would have** come.*"},{t:"p",c:"La voix passive se forme toujours avec **be** conjugué au temps voulu, suivi du **participe passé**. Au **présent** : *am, is, are* + participe passé — *The office **is cleaned** every day.* Au **prétérit** : *was, were* + participe passé — *The report **was written** yesterday.* Au **present perfect** : *has* ou *have been* + participe passé — *It **has been** done.*"},{t:"p",c:"Au **futur** : *will be* + participe passé — *It **will be** finished soon.* Avec un **modal** : modal + *be* + participe passé — *It **must be** checked.* On met en avant ce qui subit l’action ; l’auteur, s’il est précisé, est introduit par *by*."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Conditionnel type 0","If + présent, présent (vérité générale)"],["Conditionnel type 1","If + présent, will + base (réel)"],["Conditionnel type 2","If + prétérit, would + base (irréel présent)"],["Conditionnel type 3","If + past perfect, would have + participe passé (irréel passé)"],["Voix passive","be (au temps voulu) + participe passé"],["Passif au présent","am / is / are + participe passé"],["Passif au prétérit","was / were + participe passé"],["Passif au present perfect","has / have been + participe passé"],["Passif au futur","will be + participe passé"],["Passif avec un modal","modal + be + participe passé"]]}]},{h:"Les verbes irréguliers (liste)",blocks:[{t:"p",c:"Les verbes irréguliers se retiennent mieux par familles. Certains **ne changent pas du tout** : *cost – cost – cost*, *cut – cut – cut*, *put – put – put*, *read – read – read* (seule la prononciation change pour *read*). D’autres ont **le même prétérit et le même participe passé**, souvent en -ght ou en -t : *bring – brought*, *buy – bought*, *catch – caught*, *teach – taught*, *think – thought*, ou encore *keep – kept*, *sleep – slept*, *feel – felt*, *leave – left*, *meet – met*, *spend – spent*, *send – sent*, *build – built*."},{t:"p",c:"Une autre famille alterne les voyelles i – a – u : *begin – began – begun*, *drink – drank – drunk*, *sing – sang – sung*, *run – ran – run*. Beaucoup de verbes très courants ont un participe en -en ou -n : *break – broke – broken*, *choose – chose – chosen*, *drive – drove – driven*, *eat – ate – eaten*, *fall – fell – fallen*, *forget – forgot – forgotten*, *give – gave – given*, *speak – spoke – spoken*, *take – took – taken*, *write – wrote – written*, *know – knew – known*, *grow – grew – grown*, *fly – flew – flown*, *see – saw – seen*, *show – showed – shown*."},{t:"p",c:"Quelques verbes sont à connaître à part, car ils sont partout : *be – was / were – been*, *have – had – had*, *do – did – done*, *go – went – gone*, *come – came – come*, *become – became – become*, *get – got – got* (ou *gotten* en anglais américain), *make – made – made*, *say – said – said*, *tell – told – told*. La liste complète, avec le sens de chaque verbe, se trouve dans le tableau final."},{t:"table",h:"Verbes irréguliers à retenir",head:["Verbe (base – prétérit – participe passé)","Sens"],rows:[["be – was / were – been","être"],["become – became – become","devenir"],["begin – began – begun","commencer"],["break – broke – broken","casser"],["bring – brought – brought","apporter"],["build – built – built","construire"],["buy – bought – bought","acheter"],["catch – caught – caught","attraper"],["choose – chose – chosen","choisir"],["come – came – come","venir"],["cost – cost – cost","coûter"],["cut – cut – cut","couper"],["do – did – done","faire"],["drink – drank – drunk","boire"],["drive – drove – driven","conduire"],["eat – ate – eaten","manger"],["fall – fell – fallen","tomber"],["feel – felt – felt","ressentir"],["find – found – found","trouver"],["fly – flew – flown","voler"],["forget – forgot – forgotten","oublier"],["get – got – got / gotten","obtenir"],["give – gave – given","donner"],["go – went – gone","aller"],["grow – grew – grown","grandir"],["have – had – had","avoir"],["hear – heard – heard","entendre"],["keep – kept – kept","garder"],["know – knew – known","savoir"],["leave – left – left","partir"],["lose – lost – lost","perdre"],["make – made – made","fabriquer"],["meet – met – met","rencontrer"],["pay – paid – paid","payer"],["put – put – put","mettre"],["read – read – read","lire"],["run – ran – run","courir"],["say – said – said","dire"],["see – saw – seen","voir"],["sell – sold – sold","vendre"],["send – sent – sent","envoyer"],["show – showed – shown","montrer"],["sing – sang – sung","chanter"],["sit – sat – sat","s'asseoir"],["sleep – slept – slept","dormir"],["speak – spoke – spoken","parler"],["spend – spent – spent","dépenser"],["take – took – taken","prendre"],["teach – taught – taught","enseigner"],["tell – told – told","raconter"],["think – thought – thought","penser"],["understand – understood – understood","comprendre"],["wear – wore – worn","porter (un vêtement)"],["win – won – won","gagner"],["write – wrote – written","écrire"]]}]}],essentiel:["**Present perfect** (have/has + PP) = lien passé-présent ; **preterit** = action passée datée et terminée.","**Modal + base verbale** ; **conditionnels** : type 1 (present → will), type 2 (preterit → would), type 3 (past perfect → would have).","**Passif** = *be* + participe passé. Les **verbes irréguliers** se mémorisent en trois colonnes (base / preterit / PP)."],games:[{id:"lng-en-present-trou",type:"trou",title:"Conjugue — le présent",icon:"✏️",questions:[{text:"She usually ____ (go) to school by bus.",answer:"goes",explain:"Present simple, 3ᵉ personne : go → goes."},{text:"Look! They ____ (play) football right now.",answer:"are playing",explain:"Action en cours → present continuous : be + V-ing."},{text:"I ____ (not like) coffee.",answer:"don't like",alt:["do not like"],explain:"Négation au présent simple : don’t + base."},{text:"He ____ (watch) TV every evening.",answer:"watches",explain:"3ᵉ pers. d’un verbe en -ch : watch → watches."},{text:"Water ____ (boil) at 100 degrees.",answer:"boils",explain:"Vérité générale → present simple : boils."}]},{id:"lng-en-past-qcm",type:"qcm",title:"QCM — preterit vs present perfect",icon:"❓",questions:[{q:"« I ___ my keys yesterday. »",choices:["lost","have lost","was losing","lose"],answer:0,explain:"Date précise (yesterday) → preterit : lost."},{q:"« She ___ here since 2020. »",choices:["has lived","lived","lives","is living"],answer:0,explain:"« since » → present perfect : has lived."},{q:"Preterit de « to go » :",choices:["went","goed","gone","going"],answer:0,explain:"go / went / gone."},{q:"« Have you ever ___ sushi? »",choices:["eaten","ate","eat","eating"],answer:0,explain:"Present perfect + ever → participe passé : eaten."},{q:"« When I was young, I ___ in Spain. »",choices:["lived","have lived","live","am living"],answer:0,explain:"Contexte passé daté → preterit : lived."}]},{id:"lng-en-future-trou",type:"trou",title:"Conjugue — plus-que-parfait & futur",icon:"✏️",questions:[{text:"I think it ____ (rain) tomorrow.",answer:"will rain",explain:"Prévision → will + base."},{text:"Look at those clouds, it ____ (rain).",answer:"is going to rain",explain:"Indice présent → be going to."},{text:"By 2030, she ____ (finish) her studies.",answer:"will have finished",explain:"Future perfect : will have + PP."},{text:"Before he arrived, they ____ (already / leave).",answer:"had already left",explain:"Plus-que-parfait : had + PP."}]},{id:"lng-en-modal-qcm",type:"qcm",title:"QCM — les modaux",icon:"❓",questions:[{q:"Obligation forte : « You ___ wear a seatbelt. »",choices:["must","can","might","would"],answer:0,explain:"Obligation forte → must."},{q:"Conseil : « You ___ see a doctor. »",choices:["should","must","can","will"],answer:0,explain:"Conseil → should."},{q:"Capacité : « She ___ speak three languages. »",choices:["can","must","should","may"],answer:0,explain:"Capacité → can."},{q:"Après un modal, le verbe est :",choices:["à la base verbale (sans to, sans -s)","à l'infinitif avec to","en -ing","au participe passé"],answer:0,explain:"Modal + base verbale."},{q:"Permission polie : « ___ I open the window? »",choices:["May","Must","Would","Should"],answer:0,explain:"Permission polie → May I…?"}]},{id:"lng-en-cond-trou",type:"trou",title:"Conjugue — conditionnels & passif",icon:"✏️",questions:[{text:"If it rains, we ____ (stay) home.",answer:"will stay",explain:"Type 1 : if + present, will + base."},{text:"If I ____ (be) you, I would apologize.",answer:"were",alt:["was"],explain:"Type 2 : if + preterit (were)."},{text:"If I had studied, I ____ (pass) the exam.",answer:"would have passed",explain:"Type 3 : would have + PP."},{text:"The letter ____ (write) yesterday. [passif]",answer:"was written",explain:"Passif au preterit : was + PP."},{text:"English ____ (speak) all over the world. [passif]",answer:"is spoken",explain:"Passif présent : is + PP."}]},{id:"lng-en-irr-memory",type:"memory",title:"Memory — base ↔ participe passé",icon:"🧠",pairs:[{a:"go",b:"gone"},{a:"see",b:"seen"},{a:"take",b:"taken"},{a:"write",b:"written"},{a:"speak",b:"spoken"},{a:"break",b:"broken"}]},{id:"lng-en-irr-trou",type:"trou",title:"Verbes irréguliers — complète",icon:"✏️",questions:[{text:"eat → preterit = ____",answer:"ate",explain:"eat / ate / eaten."},{text:"buy → preterit = ____",answer:"bought",explain:"buy / bought / bought."},{text:"think → participe passé = ____",answer:"thought",explain:"think / thought / thought."},{text:"give → participe passé = ____",answer:"given",explain:"give / gave / given."},{text:"come → preterit = ____",answer:"came",explain:"come / came / come."}]}]},{id:"lng-en-voc",name:"Anglais — Vocabulaire",short:"Anglais · vocabulaire",keywords:"vocabulaire anglais vie quotidienne famille école travail entreprise société environnement technologie phrasal verbs connecteurs opinion",intro:"Une panoplie de vocabulaire anglais, thème par thème (à réviser en flashcards). Astuce : le dictionnaire intégré 📖 traduit aussi les phrases.",cours:[{h:"Vie quotidienne & famille",blocks:[{t:"p",c:"Pour parler de ta **family** (la famille), tu peux évoquer tes **parents**, tes **siblings** (tes frères et sœurs), c’est-à-dire ton **brother** et ta **sister**, ou encore un **child** (un enfant). Autour de la famille gravitent ton **friend** (ton ami) et ton **neighbour** (ton voisin)."},{t:"p",c:"Ton **home** (ton foyer) peut être une **house** (une maison) ou un **flat** (un appartement), avec plusieurs **rooms** (pièces) : la **kitchen** (la cuisine), la **bedroom** (la chambre). Une journée type commence quand tu **wake up** (te réveilles) et **get dressed** (t’habilles), puis vient le **breakfast** (le petit-déjeuner), premier **meal** (repas) de la journée. Il y a aussi les **chores** (les corvées) à la maison."},{t:"p",c:"Le **weekend** et les **holidays** (les vacances) laissent du temps pour un **hobby** (un loisir) : on aime **spend time** (passer du temps) **together** (ensemble), ce qui entretient une bonne **relationship** (relation)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["family","la famille"],["parents","les parents"],["siblings","les frères et sœurs"],["brother","le frère"],["sister","la sœur"],["child","l'enfant"],["friend","l'ami(e)"],["neighbour","le voisin"],["home","le foyer"],["house","la maison"],["flat","l'appartement"],["room","la pièce"],["kitchen","la cuisine"],["bedroom","la chambre"],["meal","le repas"],["breakfast","le petit-déjeuner"],["to wake up","se réveiller"],["to get dressed","s'habiller"],["chore","la corvée"],["weekend","le week-end"],["holidays","les vacances"],["hobby","le loisir"],["to spend time","passer du temps"],["relationship","la relation"],["together","ensemble"]]}]},{h:"École, études & travail",blocks:[{t:"p",c:"À l’**school** (l’école) puis à la **high school** (le lycée), le **student** (l’élève) suit les cours d’un **teacher** (professeur) dans chaque **subject** (matière). Il fait ses **homework** (devoirs), passe des **exams** (examens) et reçoit des **grades** (notes). Pour obtenir un **degree** (un diplôme), éventuellement à l’**university** (l’université), il faut **learn** (apprendre) et **study** (étudier) ; on peut **pass an exam** (réussir un examen) ou **fail** (échouer)."},{t:"p",c:"Les études apportent des **skills** (compétences) et des **knowledge** (connaissances), complétées par la **training** (la formation). Pour trouver un **job** (un emploi) et construire sa **career** (carrière), on fait souvent un **internship** (un stage), puis on **applies** (postule) et on passe un **interview** (entretien). L’employeur peut alors **hire** (embaucher) le candidat, qui rejoint ses **colleagues** (collègues) sur son **workplace** (lieu de travail) et touche un **salary** (salaire)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["school","l'école"],["high school","le lycée"],["student","l'élève"],["teacher","le professeur"],["subject","la matière"],["homework","les devoirs"],["exam","l'examen"],["grade","la note"],["degree","le diplôme"],["university","l'université"],["to learn","apprendre"],["to study","étudier"],["to pass an exam","réussir un examen"],["to fail","échouer"],["skill","la compétence"],["knowledge","les connaissances"],["training","la formation"],["job","l'emploi"],["career","la carrière"],["internship","le stage"],["to apply","postuler"],["interview","l'entretien"],["colleague","le collègue"],["workplace","le lieu de travail"],["salary","le salaire"],["to hire","embaucher"]]}]},{h:"Entreprise, gestion & finance (STMG / ETLV)",blocks:[{t:"p",c:"Une **company** (entreprise) fait du **business** (des affaires) sur un **market** (marché) où elle cherche à gagner des **market shares** (parts de marché) face à ses **competitors** (concurrents). Elle vend à des **customers** (clients) et achète à des **suppliers** (fournisseurs) au sein de sa **supply chain** (chaîne d’approvisionnement). Sa **brand** (marque) et sa **strategy** (stratégie) soutiennent sa **growth** (croissance), dans le respect de sa **CSR** (RSE)."},{t:"p",c:"Côté finances, le **turnover** (chiffre d’affaires) et le **revenue** (revenu) doivent couvrir chaque **cost** (coût) pour dégager un **profit** (bénéfice) plutôt qu’une **loss** (perte) ; le **break-even point** (seuil de rentabilité) marque ce point d’équilibre. Le **balance sheet** (bilan) et le **cash flow** (la trésorerie) renseignent sur sa santé. Pour financer un **investment** (investissement) prévu au **budget**, elle peut contracter un **loan** (emprunt) ou faire appel à ses **shareholders** (actionnaires), qui sont l’une de ses **stakeholders** (parties prenantes)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["company","l'entreprise"],["business","les affaires"],["turnover","le chiffre d'affaires"],["profit","le bénéfice"],["loss","la perte"],["balance sheet","le bilan"],["cash flow","la trésorerie"],["break-even point","le seuil de rentabilité"],["cost","le coût"],["revenue","le revenu"],["budget","le budget"],["investment","l'investissement"],["loan","l'emprunt"],["shareholder","l'actionnaire"],["stakeholder","la partie prenante"],["market","le marché"],["market share","la part de marché"],["customer","le client"],["supplier","le fournisseur"],["brand","la marque"],["growth","la croissance"],["strategy","la stratégie"],["competitor","le concurrent"],["CSR","la RSE"],["supply chain","la chaîne d'approvisionnement"]]}]},{h:"Société, politique & médias",blocks:[{t:"p",c:"Dans une **society** (société) démocratique, chaque **citizen** (citoyen) a le **right** (droit) de **vote** (voter) lors d’une **election** (élection) pour désigner le **government** (gouvernement). La **law** (loi) garantit l’**equality** (égalité) et la **freedom** (liberté), et combat la **discrimination**. Les grands enjeux, ou **issues**, sont la **poverty** (pauvreté) face à la **wealth** (richesse), le **gap** (l’écart) entre les deux, le **welfare** (la protection sociale), l’**immigration** et le contrôle de la **border** (frontière). Quand ils sont mécontents, les citoyens organisent une **protest** (manifestation)."},{t:"p",c:"Les **media** (médias), comme le **newspaper** (journal), **broadcast** (diffusent) les **news** (informations) et influencent la **public opinion** (l’opinion publique), aux côtés de l’**advertising** (la publicité). Il faut se méfier des **fake news** (fausses informations)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["society","la société"],["government","le gouvernement"],["election","l'élection"],["to vote","voter"],["citizen","le citoyen"],["right","le droit"],["law","la loi"],["equality","l'égalité"],["freedom","la liberté"],["discrimination","la discrimination"],["poverty","la pauvreté"],["wealth","la richesse"],["immigration","l'immigration"],["border","la frontière"],["protest","la manifestation"],["news","les informations"],["media","les médias"],["newspaper","le journal"],["fake news","les fausses informations"],["to broadcast","diffuser"],["advertising","la publicité"],["public opinion","l'opinion publique"],["issue","l'enjeu, le problème"],["welfare","la protection sociale"],["gap","l'écart"]]}]},{h:"Environnement & sciences",blocks:[{t:"p",c:"Protéger l’**environment** (l’environnement) est devenu urgent face au **climate change** (changement climatique) et au **global warming** (réchauffement climatique), causés par les **greenhouse gases** (gaz à effet de serre). La **pollution** et les **waste** (déchets) menacent la **wildlife** (la faune), la **forest** (forêt) et la **biodiversity** (biodiversité) : de nombreuses **species** (espèces) sont **endangered** (en voie de disparition). Les catastrophes se multiplient, comme la **drought** (sécheresse) ou la **flood** (inondation)."},{t:"p",c:"Pour **protect** (protéger) la planète, il faut **reduce** (réduire) son **carbon footprint** (empreinte carbone), **recycle** (recycler), éviter de **pollute** (polluer), économiser chaque **resource** (ressource) et développer les **renewable energies** (énergies renouvelables) pour une **energy** plus **sustainable** (durable). La **research** (recherche) et chaque **discovery** (découverte) scientifique y contribuent."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["environment","l'environnement"],["climate change","le changement climatique"],["global warming","le réchauffement climatique"],["pollution","la pollution"],["waste","les déchets"],["to recycle","recycler"],["renewable energy","les énergies renouvelables"],["greenhouse gas","le gaz à effet de serre"],["carbon footprint","l'empreinte carbone"],["sustainable","durable"],["to pollute","polluer"],["endangered","en voie de disparition"],["wildlife","la faune"],["forest","la forêt"],["drought","la sécheresse"],["flood","l'inondation"],["research","la recherche"],["discovery","la découverte"],["to reduce","réduire"],["resource","la ressource"],["biodiversity","la biodiversité"],["to protect","protéger"],["energy","l'énergie"],["species","l'espèce"]]}]},{h:"Numérique & technologies",blocks:[{t:"p",c:"La **technology** (technologie) est partout : sur le **computer** (ordinateur), le **smartphone** ou tout autre **device** (appareil), on passe des heures devant un **screen** (écran). On est **online** (en ligne), connecté à un **network** (réseau), sur les **social media** (réseaux sociaux), un **website** (site web) ou une **app** (application). On **browse** (navigue), on **download** (télécharge) et on **upload** (téléverse) des fichiers, et il faut régulièrement **update** (mettre à jour) ses **software** (logiciels)."},{t:"p",c:"Chaque **user** (utilisateur) laisse des **data** (données) : la protection de sa **privacy** (vie privée) passe par un bon **password** (mot de passe) et par la **cybersecurity** (cybersécurité). Les **algorithms** (algorithmes) et l’**artificial intelligence** (intelligence artificielle) transforment le monde **digital** (numérique), qui peut aussi créer une **addiction** (dépendance)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["technology","la technologie"],["computer","l'ordinateur"],["smartphone","le smartphone"],["screen","l'écran"],["network","le réseau"],["social media","les réseaux sociaux"],["website","le site web"],["app","l'application"],["data","les données"],["privacy","la vie privée"],["password","le mot de passe"],["to download","télécharger"],["to upload","téléverser"],["online","en ligne"],["user","l'utilisateur"],["artificial intelligence","l'intelligence artificielle"],["software","le logiciel"],["device","l'appareil"],["to browse","naviguer"],["cybersecurity","la cybersécurité"],["algorithm","l'algorithme"],["to update","mettre à jour"],["digital","numérique"],["addiction","la dépendance"]]}]},{h:"Verbes courants & phrasal verbs",blocks:[{t:"p",c:"Les verbes de base, **to be** (être), **to have** (avoir), **to do** (faire), **to make** (fabriquer), **to go** (aller) et **to get** (obtenir), servent dans presque toutes les phrases. Les **phrasal verbs** associent un verbe et une particule qui en change le sens : **to give up** (abandonner), **to give back** (rendre), **to look for** (chercher), **to look after** (s’occuper de), **to find out** (découvrir), **to figure out** (comprendre)."},{t:"p",c:"D’autres sont très utiles à l’écrit : **to point out** (souligner), **to carry out** (réaliser), **to deal with** (traiter, gérer), **to come up with** (proposer), **to take part in** (participer à), **to bring up** (évoquer), **to rely on** (compter sur). Dans la vie courante, on **grows up** (grandit), on **turns down** (refuse) une offre, on **sets up** (crée) une entreprise, on **puts off** (reporte) un rendez-vous, on **runs out of** (manque de) temps, et une machine peut **break down** (tomber en panne)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["to be","être"],["to have","avoir"],["to do","faire"],["to make","fabriquer"],["to go","aller"],["to get","obtenir"],["to give up","abandonner"],["to look for","chercher"],["to look after","s'occuper de"],["to find out","découvrir"],["to give back","rendre"],["to point out","souligner"],["to carry out","réaliser"],["to deal with","traiter, gérer"],["to come up with","proposer"],["to take part in","participer à"],["to grow up","grandir"],["to turn down","refuser"],["to set up","créer, monter"],["to put off","reporter"],["to run out of","manquer de"],["to bring up","évoquer"],["to break down","tomber en panne"],["to figure out","comprendre"],["to rely on","compter sur"]]}]},{h:"Mots de liaison & exprimer son opinion",blocks:[{t:"p",c:"Pour organiser un texte, on annonce les étapes avec **first** (d’abord), **then** (ensuite) et **finally** (enfin). On ajoute un argument avec **moreover** (de plus) ou **in addition** (en outre), on s’oppose avec **however** (cependant), **nevertheless** (néanmoins) ou **whereas** (tandis que), et on concède avec **although** (bien que). On explique avec **because** (parce que) et **indeed** (en effet), on tire une conséquence avec **therefore** (donc) ou **as a result** (par conséquent), et on illustre avec **for instance** (par exemple). Pour comparer deux idées : **on the one hand** (d’une part)… **on the other hand** (d’autre part)."},{t:"p",c:"Pour donner son avis, on écrit **in my opinion** (à mon avis) ou **I think that** (je pense que), on dit **I agree** (je suis d’accord) ou **I disagree** (je ne suis pas d’accord), et l’on cite une source avec **according to** (selon). Pour conclure, on utilise **to sum up** (pour résumer), **in conclusion** (en conclusion), **on the whole** (dans l’ensemble) ou **in fact** (en fait)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["first","d'abord"],["then","ensuite"],["finally","enfin"],["moreover","de plus"],["however","cependant"],["therefore","donc"],["because","parce que"],["although","bien que"],["in addition","en outre"],["on the one hand","d'une part"],["on the other hand","d'autre part"],["for instance","par exemple"],["in my opinion","à mon avis"],["I think that","je pense que"],["I agree","je suis d'accord"],["I disagree","je ne suis pas d'accord"],["to sum up","pour résumer"],["in conclusion","en conclusion"],["indeed","en effet"],["nevertheless","néanmoins"],["according to","selon"],["whereas","tandis que"],["as a result","par conséquent"],["in fact","en fait"],["on the whole","dans l'ensemble"]]}]}],essentiel:["Réviser le vocabulaire **par thème** et par petits blocs (10-15 min/jour) est plus efficace qu’une longue liste d’un coup.","Vocabulaire **STMG / ETLV** utile : turnover (CA), balance sheet (bilan), cash flow (trésorerie), break-even point (seuil de rentabilité), shareholder (actionnaire).","Les **phrasal verbs** (give up, look after, carry out…) se mémorisent comme un seul mot avec leur sens."],games:[{id:"lng-en-voc-daily-memory",type:"memory",title:"Memory — vie quotidienne",icon:"🧠",pairs:[{a:"family",b:"la famille"},{a:"neighbour",b:"le voisin"},{a:"meal",b:"le repas"},{a:"bedroom",b:"la chambre"},{a:"weekend",b:"le week-end"},{a:"friend",b:"l'ami"}]},{id:"lng-en-voc-biz-qcm",type:"qcm",title:"QCM — vocabulaire de l’entreprise",icon:"❓",questions:[{q:"« turnover » =",choices:["le chiffre d'affaires","le bénéfice","l'emprunt","la marque"],answer:0,explain:"turnover = chiffre d’affaires."},{q:"« shareholder » =",choices:["l'actionnaire","le fournisseur","le client","le concurrent"],answer:0,explain:"shareholder = actionnaire."},{q:"« break-even point » =",choices:["le seuil de rentabilité","le bilan","la trésorerie","la croissance"],answer:0,explain:"break-even point = seuil de rentabilité."},{q:"« supplier » =",choices:["le fournisseur","le client","le marché","le coût"],answer:0,explain:"supplier = fournisseur."},{q:"« cash flow » =",choices:["la trésorerie","le bénéfice","le budget","la perte"],answer:0,explain:"cash flow = trésorerie."}]},{id:"lng-en-voc-env-assoc",type:"association",title:"Association — environnement",icon:"🔗",pairs:[{left:"climate change",right:"le changement climatique"},{left:"waste",right:"les déchets"},{left:"renewable energy",right:"les énergies renouvelables"},{left:"drought",right:"la sécheresse"},{left:"carbon footprint",right:"l'empreinte carbone"}]},{id:"lng-en-voc-phrasal-qcm",type:"qcm",title:"QCM — phrasal verbs",icon:"❓",questions:[{q:"« to give up » =",choices:["abandonner","donner","rendre","offrir"],answer:0,explain:"to give up = abandonner."},{q:"« to look after » =",choices:["s'occuper de","chercher","regarder","ressembler à"],answer:0,explain:"to look after = s’occuper de."},{q:"« to carry out » =",choices:["réaliser","porter","emporter","continuer"],answer:0,explain:"to carry out = réaliser, mener à bien."},{q:"« to run out of » =",choices:["manquer de","sortir","courir","s’enfuir"],answer:0,explain:"to run out of = être à court de."},{q:"« to deal with » =",choices:["traiter, gérer","distribuer","vendre","négocier"],answer:0,explain:"to deal with = traiter, gérer."}]}]},{id:"lng-en-verbs",name:"Anglais — Verbes irréguliers",short:"Anglais · verbes irréguliers",keywords:"verbes irréguliers anglais prétérit participe passé irregular verbs go went gone",intro:"🇬🇧 Entraîne-toi aux six verbes irréguliers du cours : chaque partie sélectionne et mélange dix questions de cette banque.",cours:[{h:"Verbes irréguliers : base, prétérit, participe passé",blocks:[{t:"p",c:"Chaque verbe irrégulier s’apprend avec ses trois formes : base, prétérit, participe passé. **Go** donne *went* puis *gone* (aller) ; **see** donne *saw* puis *seen* (voir) ; **take** donne *took* puis *taken* (prendre). **Make** donne *made* puis *made* (fabriquer) ; **come** donne *came* puis *come* (venir) ; **write** donne *wrote* puis *written* (écrire)."},{t:"tip",c:"Structure : **base – prétérit – participe passé**. Le mieux : les réviser par familles de sons."},{t:"table",h:"Verbes irréguliers à retenir",head:["Verbe (base – prétérit – participe passé)","Sens"],rows:[["go – went – gone","aller"],["see – saw – seen","voir"],["take – took – taken","prendre"],["make – made – made","fabriquer"],["come – came – come","venir"],["write – wrote – written","écrire"]]}]}],games:[{id:"lng-en-verbs-gen",type:"verbs",title:"Verbes irréguliers — entraînement",icon:"🔤",count:10,questions:[{prompt:"Prétérit de to go (aller) ?",answer:"went",explain:"go – went – gone (aller)"},{prompt:"Participe passé de to go (aller) ?",answer:"gone",explain:"go – went – gone (aller)"},{prompt:"Quel est l’infinitif dont le prétérit est « went » ? (aller)",answer:"go",explain:"go – went – gone (aller)"},{prompt:"Prétérit de to see (voir) ?",answer:"saw",explain:"see – saw – seen (voir)"},{prompt:"Participe passé de to see (voir) ?",answer:"seen",explain:"see – saw – seen (voir)"},{prompt:"Quel est l’infinitif dont le prétérit est « saw » ? (voir)",answer:"see",explain:"see – saw – seen (voir)"},{prompt:"Prétérit de to take (prendre) ?",answer:"took",explain:"take – took – taken (prendre)"},{prompt:"Participe passé de to take (prendre) ?",answer:"taken",explain:"take – took – taken (prendre)"},{prompt:"Quel est l’infinitif dont le prétérit est « took » ? (prendre)",answer:"take",explain:"take – took – taken (prendre)"},{prompt:"Prétérit de to make (fabriquer) ?",answer:"made",explain:"make – made – made (fabriquer)"},{prompt:"Participe passé de to make (fabriquer) ?",answer:"made",explain:"make – made – made (fabriquer)"},{prompt:"Quel est l’infinitif dont le prétérit est « made » ? (fabriquer)",answer:"make",explain:"make – made – made (fabriquer)"},{prompt:"Prétérit de to come (venir) ?",answer:"came",explain:"come – came – come (venir)"},{prompt:"Participe passé de to come (venir) ?",answer:"come",explain:"come – came – come (venir)"},{prompt:"Quel est l’infinitif dont le prétérit est « came » ? (venir)",answer:"come",explain:"come – came – come (venir)"},{prompt:"Prétérit de to write (écrire) ?",answer:"wrote",explain:"write – wrote – written (écrire)"},{prompt:"Participe passé de to write (écrire) ?",answer:"written",explain:"write – wrote – written (écrire)"},{prompt:"Quel est l’infinitif dont le prétérit est « wrote » ? (écrire)",answer:"write",explain:"write – wrote – written (écrire)"}]}]},{id:"lng-en-grammar-ex",name:"Anglais — Grammaire (exercices)",short:"Anglais · grammaire",keywords:"grammaire anglaise exercices a an some any much many comparatif superlatif présent simple",intro:"🇬🇧 Les règles de grammaire en exercices générés : articles, présent, comparatifs, some/any, temps du passé… De nouveaux items à chaque fois.",cours:[{h:"Règles clés : a / an, 3ᵉ personne en -s, comparatif, some / any, much / many",blocks:[{t:"list",c:["**a / an** selon le son (a car, an apple).","Présent simple : **+s** à la 3ᵉ personne (he work**s**).","Comparatif : court **+er**, long **more** + adj.","**some / any**, **much / many**, **this / these**."]},{t:"p",c:"On emploie **a** devant un son consonne (**a car**) et **an** devant un son voyelle (**an apple**). Au présent simple, la troisième personne du singulier prend **-s** : **he works**, **she plays**."},{t:"p",c:"Au comparatif, un adjectif court prend **-er** : **fast → faster**. Pour un adjectif long, on utilise **more** : **interesting → more interesting**."},{t:"p",c:"On emploie généralement **some** dans une phrase affirmative (**I have some money**) et **any** dans une phrase négative (**I do not have any money**). **Much** accompagne un nom indénombrable (**much money**), **many** un nom dénombrable au pluriel (**many books**)."},{t:"p",c:"Pour désigner quelque chose de proche, **this** s’utilise au singulier (**this book here**) et **these** au pluriel (**these books here**)."},{t:"tip",c:"Chaque partie mélange **dix questions sur les règles et exemples de ce cours**. Certaines questions peuvent revenir pour consolider tes acquis."}]}],games:[{id:"lng-en-grammar-gen",type:"grammar",title:"Grammaire — exercices variés",icon:"🧩",count:10,questions:[{prompt:"Article : ____ car.",answer:"a",explain:"a devant un son consonne."},{prompt:"Article : ____ apple.",answer:"an",explain:"an devant un son voyelle."},{prompt:"Présent simple : He ____ (work) every day.",answer:"works",explain:"Au présent simple, on ajoute -s à la troisième personne du singulier."},{prompt:"Présent simple : She ____ (play) every day.",answer:"plays",explain:"Au présent simple, on ajoute -s à la troisième personne du singulier."},{prompt:"Comparatif : This car is ____ (fast) than that one.",answer:"faster",explain:"Comparatif d’un adjectif court : +er."},{prompt:"Comparatif : This course is ____ (interesting) than that one.",answer:"more interesting",explain:"Comparatif d’un adjectif long : more + adjectif."},{prompt:"some / any : I have ____ money.",answer:"some",explain:"some dans une phrase affirmative."},{prompt:"some / any : I do not have ____ money.",answer:"any",explain:"any dans une phrase négative."},{prompt:"much / many : How ____ money do you have?",answer:"much",explain:"much avec un nom indénombrable."},{prompt:"much / many : How ____ books do you have?",answer:"many",explain:"many avec un nom dénombrable au pluriel."},{prompt:"this / these : ____ book here.",answer:"this",explain:"this devant un nom singulier."},{prompt:"this / these : ____ books here.",answer:"these",explain:"these devant un nom pluriel."}]}]},{id:"lng-en-comp",name:"Anglais — Compréhension",short:"Anglais · compréhension",keywords:"compréhension orale écrite écoute lecture niveau A2 B1 B2 audio texte questions correction",intro:"🇬🇧 Compréhensions orales (écoute) et écrites, classées par niveau. Choisis ton niveau, réponds aux questions, puis découvre la correction.",cours:[{h:"Niveau A2 — Débutant",blocks:[{t:"p",c:"Textes et dialogues **simples** (vie quotidienne). Idéal pour se lancer."}]},{h:"Niveau B1 — Intermédiaire",blocks:[{t:"p",c:"Récits et situations **plus longs** (travail, voyages, école)."}]},{h:"Niveau B2 — Avancé",blocks:[{t:"p",c:"Sujets **d’actualité et professionnels** (entreprise, société)."}]}],games:[{type:"comprehension",icon:"📖",id:"cmp-en-a2-read",lang:"en",listen:!1,level:"A2",title:"Read — My weekend",topic:"My weekend",text:"On Saturday morning, I get up at nine o'clock. I have breakfast with my family and then I do my homework. In the afternoon, I play football with my friends in the park. On Sunday, we visit my grandparents. My grandmother cooks a big lunch and we eat together. I love the weekend because I can relax and see the people I love.",questions:[{q:"What time does the writer get up on Saturday?",choices:["At 7","At 9","At 11"],answer:1,explain:"“I get up at nine o’clock.”"},{q:"What does the writer do on Saturday afternoon?",choices:["Homework","Play football","Visit grandparents"],answer:1,explain:"Football in the park in the afternoon."},{q:"Who cooks lunch on Sunday?",choices:["The writer","The mother","The grandmother"],answer:2,explain:"“My grandmother cooks a big lunch.”"},{q:"Why does the writer love the weekend?",choices:["To work","To relax and see loved ones","To travel"],answer:1,explain:"“I can relax and see the people I love.”"}]},{type:"comprehension",icon:"🎧",id:"cmp-en-a2-listen",lang:"en",listen:!0,level:"A2",title:"Listen — At the shop",topic:"At the shop",text:"Hello! Can I help you? Yes, please. I am looking for a blue T-shirt. What size do you need? Medium, please. Here you are. It costs fifteen pounds. Can I pay by card? Of course. Thank you very much. Have a nice day!",questions:[{q:"What is the customer looking for?",choices:["A blue T-shirt","A red jacket","Blue jeans"],answer:0,explain:"“a blue T-shirt”."},{q:"What size does the customer want?",choices:["Small","Medium","Large"],answer:1,explain:"“Medium, please.”"},{q:"How much does it cost?",choices:["£15","£50","£13"],answer:0,explain:"“It costs fifteen pounds.”"},{q:"How does the customer pay?",choices:["Cash","By card","By cheque"],answer:1,explain:"“Can I pay by card?”"}]},{type:"comprehension",icon:"📖",id:"cmp-en-b1-read",lang:"en",listen:!1,level:"B1",title:"Read — A summer job",topic:"A summer job",text:"Last summer, Emma worked in a small café by the sea. She started early, at seven in the morning, and served coffee to tourists. The job was tiring but she earned enough money to buy a new laptop. She also improved her English because many customers came from abroad. At the end of August, the owner offered her a job for the next summer. Emma was proud: it was her first real work experience.",questions:[{q:"Where did Emma work?",choices:["In a shop","In a café by the sea","In an office"],answer:1,explain:"“a small café by the sea”."},{q:"What did she buy with her money?",choices:["A phone","A laptop","A bike"],answer:1,explain:"“to buy a new laptop”."},{q:"Why did her English improve?",choices:["She took a class","Customers came from abroad","She read books"],answer:1,explain:"“many customers came from abroad”."},{q:"What did the owner offer at the end?",choices:["More money","A job next summer","A holiday"],answer:1,explain:"“offered her a job for the next summer”."}]},{type:"comprehension",icon:"🎧",id:"cmp-en-b1-listen",lang:"en",listen:!0,level:"B1",title:"Listen — Booking a room",topic:"Booking a hotel room",text:"Good evening, Sea View Hotel, how can I help you? Hello, I'd like to book a double room for two nights, please. Certainly. When would you like to arrive? On Friday the tenth. And how many people? Two adults. The room is ninety euros per night, breakfast included. That's fine. Could I have your name, please? Yes, it's David Miller. Perfect, your room is booked. See you on Friday!",questions:[{q:"What type of room does the man want?",choices:["A single room","A double room","A family room"],answer:1,explain:"“a double room”."},{q:"How many nights?",choices:["One","Two","Three"],answer:1,explain:"“for two nights”."},{q:"What is included in the price?",choices:["Dinner","Breakfast","Parking"],answer:1,explain:"“breakfast included”."},{q:"When will the man arrive?",choices:["Friday the 10th","Saturday","Sunday"],answer:0,explain:"“On Friday the tenth.”"}]},{type:"comprehension",icon:"📖",id:"cmp-en-b2-read",lang:"en",listen:!1,level:"B2",title:"Read — Remote work",topic:"Remote work",text:"Since the pandemic, remote work has become common in many companies. Employees who work from home often say they are more productive and save time because they no longer commute. However, remote work also has drawbacks. Some workers feel isolated and find it harder to separate their professional and personal lives. To address these issues, many firms now offer a hybrid model: staff spend a few days in the office and the rest at home. Managers must learn to trust their teams and to measure results rather than hours.",questions:[{q:"What is one advantage of remote work mentioned?",choices:["Higher salary","No commuting","More holidays"],answer:1,explain:"“they no longer commute”."},{q:"What is a drawback?",choices:["Feeling isolated","Too many meetings","Lower wages"],answer:0,explain:"“Some workers feel isolated”."},{q:"What is the “hybrid model”?",choices:["Only working at home","A mix of office and home","Working at night"],answer:1,explain:"“a few days in the office and the rest at home”."},{q:"What should managers focus on?",choices:["Hours worked","Results","Attendance"],answer:1,explain:"“measure results rather than hours”."}]},{type:"comprehension",icon:"🎧",id:"cmp-en-b2-listen",lang:"en",listen:!0,level:"B2",title:"Listen — Job interview",topic:"A job interview",text:"Thank you for coming today. Could you tell me about yourself? Of course. I recently graduated in business management and I did a six-month internship in marketing. Why do you want to work for our company? I admire your brand and I believe my digital skills could help you reach younger customers. What is your greatest weakness? Sometimes I focus too much on details, but I am learning to manage my time better. Great. We will contact you next week.",questions:[{q:"What did the candidate study?",choices:["Law","Business management","Engineering"],answer:1,explain:"“I recently graduated in business management”."},{q:"How long was the internship?",choices:["Three months","Six months","One year"],answer:1,explain:"“a six-month internship”."},{q:"Why does the candidate want the job?",choices:["High salary","To reach younger customers with digital skills","Short hours"],answer:1,explain:"“my digital skills could help you reach younger customers”."},{q:"What weakness does the candidate mention?",choices:["Being late","Focusing too much on details","Poor English"],answer:1,explain:"“I focus too much on details”."}]}]},{id:"lng-es-gram",name:"Espagnol — Toutes les conjugaisons",short:"Espagnol · conjugaison",keywords:"ser estar presente indefinido imperfecto perfecto pluscuamperfecto futuro condicional subjuntivo imperativo gerundio gustar verbes irréguliers espagnol conjugaison",intro:"Toutes les conjugaisons espagnoles : ser/estar, présent, passés, futur, conditionnel, subjonctif, impératif, gérondif et les verbes irréguliers clés.",cours:[{h:"Ser et estar, le présent et ses irréguliers",blocks:[{t:"p",c:"Au présent, **ser** se conjugue *soy, eres, es, somos, sois, son*, et **estar** se conjugue *estoy, estás, está, estamos, estáis, están*. Les deux verbes se traduisent par « être », mais ils ne s’emploient pas de la même façon."},{t:"p",c:"**Ser** exprime ce qui est **permanent** ou définit la personne : l’**identité**, l’**origine**, la **profession**, l’**heure** — *Soy español*, *Son las tres*. **Estar** exprime un **état passager** ou une **situation dans l’espace** — *Estoy cansado* (je suis fatigué), *Está en Madrid* (il est à Madrid)."},{t:"p",c:"Au présent, les verbes réguliers en **-ar**, comme *hablar*, se conjuguent *hablo, hablas, habla, hablamos, habláis, hablan*. Les verbes en **-er**, comme *comer*, donnent *como, comes, come, comemos, coméis, comen*."},{t:"p",c:"Les verbes en **-ir**, comme *vivir*, ont les mêmes terminaisons que les verbes en -er, sauf à *nosotros* et *vosotros* : *vivo, vives, vive, vivimos, vivís, viven*."},{t:"p",c:"**Irréguliers fréquents au présent** : tener → *tengo, tienes, tiene…* · ir → *voy, vas, va, vamos, vais, van* · hacer → *hago* · poder → *puedo, puedes…* · querer → *quiero…*"},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Ser (présent)","soy, eres, es, somos, sois, son"],["Estar (présent)","estoy, estás, está, estamos, estáis, están"],["Emploi de ser","Permanent : identité, origine, profession, heure (Soy español, Son las tres)"],["Emploi de estar","État passager, lieu (Estoy cansado, Está en Madrid)"],["Présent en -ar (hablar)","hablo, hablas, habla, hablamos, habláis, hablan"],["Présent en -er (comer)","como, comes, come, comemos, coméis, comen"],["Présent en -ir (vivir)","vivo, vives, vive, vivimos, vivís, viven"],["Irréguliers fréquents au présent","tener → tengo ; ir → voy ; hacer → hago ; poder → puedo ; querer → quiero"]]}]},{h:"Le passé simple (indefinido) et l’imparfait (imperfecto)",blocks:[{t:"p",c:"Au passé simple, l’***indefinido***, les verbes en **-ar** comme *hablar* se conjuguent *hablé, hablaste, habló, hablamos, hablasteis, hablaron* ; attention aux accents de *hablé* et *habló*, qui distinguent ces formes du présent."},{t:"p",c:"Les verbes en **-er** et en **-ir** partagent les mêmes terminaisons : *comí, comiste, comió, comimos, comisteis, comieron*."},{t:"p",c:"À l’imparfait, l’***imperfecto***, les verbes en **-ar** prennent des terminaisons en **-aba** : *hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban*. Les verbes en **-er** et en **-ir** prennent des terminaisons en **-ía** : *comía, comías, comía, comíamos, comíais, comían*. Seuls trois verbes sont irréguliers à l’imparfait : *ser* (era), *ir* (iba) et *ver* (veía)."},{t:"p",c:"**Emploi** : *indefinido* = action **datée et ponctuelle** ; *imperfecto* = **décor, description, habitude**. Indefinidos irréguliers : ser/ir → *fui*, tener → *tuve*, hacer → *hice*, estar → *estuve*, poder → *pude*, decir → *dije*."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Indefinido en -ar (hablar)","hablé, hablaste, habló, hablamos, hablasteis, hablaron"],["Indefinido en -er/-ir (comer)","comí, comiste, comió, comimos, comisteis, comieron"],["Imperfecto en -ar (hablar)","hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban"],["Imperfecto en -er/-ir (comer)","comía, comías, comía, comíamos, comíais, comían"],["Emploi de l’indefinido","Action datée et ponctuelle"],["Emploi de l’imperfecto","Décor, description, habitude"],["Indefinidos irréguliers","ser/ir → fui ; tener → tuve ; hacer → hice ; estar → estuve ; poder → pude ; decir → dije"]]}]},{h:"Le passé composé et le plus-que-parfait (haber + participe)",blocks:[{t:"p",c:"Le **passé composé** (*pretérito perfecto*) se forme avec l’auxiliaire **haber** au présent suivi du **participe passé** : *he hablado, has hablado, ha hablado, hemos hablado, habéis hablado, han hablado*."},{t:"p",c:"Le **plus-que-parfait** (*pluscuamperfecto*) se forme avec **haber à l’imparfait** suivi du participe : *había hablado, habías hablado, había hablado, habíamos hablado, habíais hablado, habían hablado*. Le participe passé régulier se termine en **-ado** pour les verbes en -ar et en **-ido** pour les verbes en -er et -ir, et il reste invariable."},{t:"p",c:"Plusieurs participes passés sont irréguliers et doivent être appris par cœur : **hacer** donne *hecho*, **decir** donne *dicho*, **ver** donne *visto*, **escribir** donne *escrito*, **poner** donne *puesto*, **volver** donne *vuelto*, **abrir** donne *abierto*, **romper** donne *roto* et **morir** donne *muerto*."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Pretérito perfecto","haber au présent + participe (he, has, ha, hemos, habéis, han hablado)"],["Pluscuamperfecto","haber à l’imparfait + participe (había, habías, había, habíamos, habíais, habían hablado)"],["Participe passé régulier","-ado (hablar → hablado) ; -ido (comer → comido)"],["Participes irréguliers","hacer → hecho ; decir → dicho ; ver → visto"],["Participes irréguliers (suite)","escribir → escrito ; poner → puesto ; volver → vuelto"],["Participes irréguliers (fin)","abrir → abierto ; romper → roto ; morir → muerto"]]}]},{h:"Le futur et le conditionnel : terminaisons et radicaux irréguliers",blocks:[{t:"p",c:"Le **futur** se forme en ajoutant à l’infinitif les terminaisons *-é, -ás, -á, -emos, -éis, -án* : *hablaré, hablarás, hablará, hablaremos, hablaréis, hablarán*."},{t:"p",c:"Le **conditionnel** se forme de la même façon, avec les terminaisons *-ía, -ías, -ía, -íamos, -íais, -ían* : *hablaría, hablarías, hablaría, hablaríamos, hablaríais, hablarían*. Les deux temps partagent les mêmes terminaisons pour les trois groupes de verbes."},{t:"p",c:"On ajoute les terminaisons à **l’infinitif**. **Radicaux irréguliers** (communs au futur et au conditionnel) : tener → *tendr-*, poder → *podr-*, hacer → *har-*, decir → *dir-*, poner → *pondr-*, salir → *saldr-*, venir → *vendr-*, querer → *querr-*, saber → *sabr-*, haber → *habr-*."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Futuro (hablar)","hablaré, hablarás, hablará, hablaremos, hablaréis, hablarán"],["Condicional (hablar)","hablaría, hablarías, hablaría, hablaríamos, hablaríais, hablarían"],["Radicaux irréguliers du futur et du conditionnel","tendr-, podr-, har-, dir-, pondr-, saldr-, vendr-, querr-, sabr-, habr-"]]}]},{h:"Le subjonctif présent et l’impératif",blocks:[{t:"p",c:"Au **subjonctif présent**, les verbes en **-ar** prennent des terminaisons en **-e** : *hable, hables, hable, hablemos, habléis, hablen*. Les verbes en **-er** et en **-ir** prennent des terminaisons en **-a** : *coma, comas, coma, comamos, comáis, coman*. C’est l’« échange » des voyelles qui permet de le reconnaître."},{t:"p",c:"**Emploi du subjonctif** : souhait, doute, nécessité, ordre négatif — après *que*, *ojalá*, *es necesario que*, *quiero que*… (les terminaisons « s’échangent » : -ar prend des -e, -er/-ir des -a)."},{t:"p",c:"À l’**impératif affirmatif**, la forme de **tú** est identique à la troisième personne du présent : *habla, come, vive*. La forme de **usted** emprunte le subjonctif : *hable, coma, viva*. La forme de **vosotros** se construit en remplaçant le -r de l’infinitif par un **-d** : *hablad, comed, vivid*."},{t:"p",c:"À l’**impératif négatif**, on utilise toujours le **subjonctif** précédé de *no* : *no hables, no comas, no vivas* pour tú ; *no hable, no coma, no viva* pour usted ; *no habléis, no comáis, no viváis* pour vosotros."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Subjuntivo presente en -ar (hablar)","hable, hables, hable, hablemos, habléis, hablen"],["Subjuntivo presente en -er/-ir (comer)","coma, comas, coma, comamos, comáis, coman"],["Emploi du subjonctif","Souhait, doute, nécessité, ordre négatif (que, ojalá, es necesario que, quiero que)"],["Impératif affirmatif (tú)","habla / come / vive"],["Impératif affirmatif (usted)","hable / coma / viva"],["Impératif affirmatif (vosotros)","hablad / comed / vivid"],["Impératif négatif","no + subjonctif (no hables, no hable, no habléis)"]]}]},{h:"Le gérondif, l’obligation (tener que, hay que) et gustar",blocks:[{t:"p",c:"Le **gérondif** se forme en remplaçant la terminaison de l’infinitif : **-ar** devient **-ando** (*hablar → hablando*) et **-er** ou **-ir** deviennent **-iendo** (*comer → comiendo*, *vivir → viviendo*). Avec **estar**, il exprime une action **en train de se dérouler** : *Estoy comiendo*, je suis en train de manger."},{t:"p",c:"L’espagnol exprime l’obligation de trois façons. **Tener que** + infinitif exprime une obligation **personnelle** : *Tengo que estudiar*, je dois étudier. **Hay que** + infinitif exprime une obligation **impersonnelle**, valable pour tous : *Hay que trabajar*, il faut travailler. **Deber** + infinitif signifie « **devoir** », souvent avec une nuance de conseil : *Debes descansar*, tu dois te reposer."},{t:"p",c:"**Verbes type *gustar*** : le sujet est la chose aimée → *Me **gusta** el cine* (sing.) / *Me **gustan** los libros* (plur.). Même construction : *encantar, interesar, doler, faltar*."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Gérondif en -ar","-ando (hablar → hablando)"],["Gérondif en -er/-ir","-iendo (comer → comiendo, vivir → viviendo)"],["Estar + gérondif","Être en train de (Estoy comiendo)"],["Tener que + infinitif","Obligation personnelle (Tengo que estudiar)"],["Hay que + infinitif","Obligation impersonnelle (Hay que trabajar)"],["Deber + infinitif","Devoir (Debes descansar)"],["Verbes type gustar","Le sujet est la chose aimée : me gusta el cine / me gustan los libros"]]}]},{h:"Verbes irréguliers clés (liste)",blocks:[{t:"p",c:"Les verbes irréguliers les plus fréquents changent souvent à la première personne du présent : *tengo* (tener), *hago* (hacer), *digo* (decir), *pongo* (poner), *vengo* (venir), *salgo* (salir), *traigo* (traer), *oigo* (oír), *conduzco* (conducir), *doy* (dar), *veo* (ver), *sé* (saber). D’autres changent leur radical : *puedo* (poder), *quiero* (querer), *vuelvo* (volver). *Ser* donne *soy*, *estar* donne *estoy*, *ir* donne *voy* et *haber* donne *he*."},{t:"p",c:"Au passé simple, beaucoup ont un radical irrégulier : *estuve* (estar), *tuve* (tener), *hube* (haber), *hice* (hacer), *dije* (decir), *pude* (poder), *puse* (poner), *quise* (querer), *supe* (saber), *vine* (venir), *traje* (traer), *conduje* (conducir). *Ser* et *ir* ont la même forme, *fui* ; *ver* donne *vi* et *dar* donne *di*, tandis que *salí*, *leí*, *oí* et *volví* restent réguliers. Côté participes, retiens *hecho*, *visto*, *dicho*, *puesto* et *vuelto* ; les autres sont réguliers, comme *sido*, *estado*, *tenido* ou *ido*."},{t:"table",h:"Verbes irréguliers à retenir",head:["Verbe (présent yo, indefinido yo, participe)","Sens"],rows:[["ser (soy, fui, sido)","être (permanent)"],["estar (estoy, estuve, estado)","être (état, lieu)"],["tener (tengo, tuve, tenido)","avoir"],["haber (he, hube, habido)","avoir (auxiliaire)"],["hacer (hago, hice, hecho)","faire"],["ir (voy, fui, ido)","aller"],["ver (veo, vi, visto)","voir"],["dar (doy, di, dado)","donner"],["decir (digo, dije, dicho)","dire"],["poder (puedo, pude, podido)","pouvoir"],["poner (pongo, puse, puesto)","mettre"],["querer (quiero, quise, querido)","vouloir, aimer"],["saber (sé, supe, sabido)","savoir"],["venir (vengo, vine, venido)","venir"],["salir (salgo, salí, salido)","sortir"],["traer (traigo, traje, traído)","apporter"],["leer (leo, leí, leído)","lire"],["oír (oigo, oí, oído)","entendre"],["volver (vuelvo, volví, vuelto)","revenir"],["conducir (conduzco, conduje, conducido)","conduire"]]}]}],essentiel:["**Ser** = permanent (identité, origine, heure, profession) ; **Estar** = état, lieu, situation temporaire.","**Indefinido** = action datée et ponctuelle ; **Imperfecto** = décor, description, habitude.","**Futur/conditionnel** : terminaisons sur l’infinitif (radicaux irréguliers : tendr-, podr-, har-…). **Gustar** s’accorde avec la chose aimée."],games:[{id:"lng-es-serestar-tri",type:"tri",title:"Tri — Ser ou Estar ?",icon:"🗂️",instruction:"Classe chaque phrase selon le bon auxiliaire.",categories:[{id:"ser",label:"SER"},{id:"estar",label:"ESTAR"}],items:[{text:"María ___ profesora (profession)",cat:"ser"},{text:"Nosotros ___ en Madrid (lieu)",cat:"estar"},{text:"La sopa ___ muy caliente (état)",cat:"estar"},{text:"___ las tres (heure)",cat:"ser"},{text:"Yo ___ cansado (état passager)",cat:"estar"},{text:"Ella ___ de España (origine)",cat:"ser"}]},{id:"lng-es-presente-trou",type:"trou",title:"Conjugue — le présent",icon:"✏️",questions:[{text:"Yo ____ (hablar) español.",answer:"hablo",explain:"-ar : yo hablo."},{text:"Nosotros ____ (comer) a las dos.",answer:"comemos",explain:"-er : nosotros comemos."},{text:"Ellos ____ (vivir) en Sevilla.",answer:"viven",explain:"-ir : ellos viven."},{text:"Yo ____ (tener) dos hermanos.",answer:"tengo",explain:"tener irrégulier : tengo."},{text:"¿Tú ____ (ir) al cine?",answer:"vas",explain:"ir : voy, vas, va…"}]},{id:"lng-es-pasado-tri",type:"tri",title:"Tri — Indefinido ou Imperfecto ?",icon:"🗂️",instruction:"Classe selon le temps du passé approprié.",categories:[{id:"ind",label:"Indefinido (daté)"},{id:"imp",label:"Imperfecto (décor/habitude)"}],items:[{text:"Ayer comí en un restaurante",cat:"ind"},{text:"Cuando era niño, jugaba al fútbol",cat:"imp"},{text:"Ella habló por teléfono a las 8",cat:"ind"},{text:"Todos los días iba a la escuela",cat:"imp"},{text:"Llegó y saludó a todos",cat:"ind"},{text:"Hacía sol y los pájaros cantaban",cat:"imp"}]},{id:"lng-es-perfecto-trou",type:"trou",title:"Conjugue — perfecto & participes",icon:"✏️",questions:[{text:"Hoy yo ____ (comer) paella. [perfecto]",answer:"he comido",explain:"Perfecto : he + participio (comido)."},{text:"Participio de « hacer » = ____",answer:"hecho",explain:"hacer → hecho."},{text:"Participio de « escribir » = ____",answer:"escrito",explain:"escribir → escrito."},{text:"Nosotros ____ (ver) esa película. [perfecto]",answer:"hemos visto",explain:"ver → visto : hemos visto."},{text:"Cuando llegué, ellos ya ____ (salir). [pluscuamperfecto]",answer:"habían salido",explain:"Pluscuamperfecto : habían + participio."}]},{id:"lng-es-futuro-trou",type:"trou",title:"Conjugue — futur & conditionnel",icon:"✏️",questions:[{text:"Mañana yo ____ (hablar) con el jefe. [futuro]",answer:"hablaré",explain:"Futuro : hablaré."},{text:"Ellos ____ (tener) que estudiar. [futuro]",answer:"tendrán",explain:"Radical irrégulier tendr- : tendrán."},{text:"Yo ____ (hacer) los deberes esta noche. [futuro]",answer:"haré",explain:"Radical har- : haré."},{text:"Si tuviera dinero, ____ (viajar, yo). [condicional]",answer:"viajaría",explain:"Condicional : viajaría."},{text:"¿____ (poder, tú) ayudarme? [condicional]",answer:"podrías",explain:"Radical podr- : podrías."}]},{id:"lng-es-subj-qcm",type:"qcm",title:"QCM — subjonctif & impératif",icon:"❓",questions:[{q:"« Quiero que tú ___ aquí. »",choices:["estés","estás","estar","estarás"],answer:0,explain:"Après « quiero que » → subjonctif : estés."},{q:"« Ojalá ___ sol mañana. »",choices:["haga","hace","hará","hacer"],answer:0,explain:"ojalá + subjonctif : haga."},{q:"Impératif négatif (tú) : « No ___ eso. »",choices:["hagas","haces","haz","hagáis"],answer:0,explain:"Impératif négatif = subjonctif : no hagas."},{q:"On utilise le subjonctif après :",choices:["es necesario que","porque","es verdad que","siempre"],answer:0,explain:"es necesario que + subjonctif."},{q:"Impératif affirmatif (tú) de « comer » :",choices:["come","comes","coma","comed"],answer:0,explain:"Impératif tú : come."}]},{id:"lng-es-gustar-qcm",type:"qcm",title:"QCM — gérondif, obligation & gustar",icon:"❓",questions:[{q:"« Me ___ los libros. »",choices:["gustan","gusta","gusto","gustar"],answer:0,explain:"Accord avec la chose aimée (pluriel) : gustan."},{q:"« A ella le ___ el chocolate. »",choices:["gusta","gustan","gusto","gustas"],answer:0,explain:"Singulier (el chocolate) : gusta."},{q:"« Il faut étudier » se dit :",choices:["Hay que estudiar","Tengo estudiar","Es estudiar","Estar estudiar"],answer:0,explain:"Obligation impersonnelle : hay que + infinitif."},{q:"Gérondif de « hablar » :",choices:["hablando","hablado","hablar","hablo"],answer:0,explain:"-ar → -ando : hablando."},{q:"« Estoy ___ (comer) ahora. »",choices:["comiendo","comido","comer","como"],answer:0,explain:"estar + gérondif : comiendo."}]},{id:"lng-es-irr-memory",type:"memory",title:"Memory — infinitif ↔ indefinido (yo)",icon:"🧠",pairs:[{a:"ser / ir",b:"fui"},{a:"tener",b:"tuve"},{a:"hacer",b:"hice"},{a:"estar",b:"estuve"},{a:"poder",b:"pude"},{a:"decir",b:"dije"}]}]},{id:"lng-es-voc",name:"Espagnol — Vocabulaire",short:"Espagnol · vocabulaire",keywords:"vocabulario español vida cotidiana familia estudios trabajo empresa economía sociedad memoria medio ambiente tecnología verbos conectores opinión",intro:"Une panoplie de vocabulaire espagnol, thème par thème (à réviser en flashcards). Le dictionnaire intégré 📖 traduit aussi les phrases.",cours:[{h:"La vida cotidiana y la familia",blocks:[{t:"p",c:"Pour parler de **la familia** (la famille), on présente **los padres** (les parents), **el hermano** (le frère) et **la hermana** (la sœur), **el hijo** (le fils) et **la hija** (la fille). Autour d’elle, il y a **el amigo** (l’ami) et **el vecino** (le voisin)."},{t:"p",c:"On vit dans **la casa** (la maison) ou dans **el piso** (l’appartement), avec **la habitación** (la chambre) et **la cocina** (la cuisine). **La vida cotidiana** (la vie quotidienne) commence quand on va **despertarse** (se réveiller) et **vestirse** (s’habiller), puis vient **el desayuno** (le petit-déjeuner), premier repas, **la comida**. Il y a aussi **la tarea** (la tâche) à accomplir. **El fin de semana** (le week-end) et **las vacaciones** (les vacances) sont consacrés à **el ocio** (les loisirs) : on aime **pasar tiempo** (passer du temps) **juntos** (ensemble), ce qui renforce **la relación** (la relation)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["la familia","la famille"],["los padres","les parents"],["el hermano","le frère"],["la hermana","la sœur"],["el hijo","le fils"],["la hija","la fille"],["el amigo","l'ami"],["el vecino","le voisin"],["la casa","la maison"],["el piso","l'appartement"],["la habitación","la chambre"],["la cocina","la cuisine"],["la comida","le repas"],["el desayuno","le petit-déjeuner"],["despertarse","se réveiller"],["vestirse","s'habiller"],["la tarea","la tâche"],["el fin de semana","le week-end"],["las vacaciones","les vacances"],["el ocio","les loisirs"],["pasar tiempo","passer du temps"],["la vida cotidiana","la vie quotidienne"],["juntos","ensemble"],["la relación","la relation"]]}]},{h:"Estudios y trabajo",blocks:[{t:"p",c:"Au **colegio** (l’école) puis à l’**instituto** (le lycée), **el alumno** (l’élève) suit les cours de **el profesor** (le professeur) dans chaque **asignatura** (matière). Il fait **los deberes** (les devoirs), passe **el examen** (l’examen) et reçoit **la nota** (la note). Pour obtenir **el título** (le diplôme), parfois à **la universidad** (l’université), il faut **aprender** (apprendre) et **estudiar** (étudier) ; on peut **aprobar** (réussir) ou **suspender** (échouer)."},{t:"p",c:"Les études donnent **la competencia** (la compétence) et **los conocimientos** (les connaissances), complétées par **la formación** (la formation). Pour trouver **el empleo** (l’emploi) ou **el trabajo** (le travail) et construire **la carrera** (la carrière), on fait **las prácticas** (le stage), puis on passe **la entrevista** (l’entretien). L’employeur peut **contratar** (embaucher) le candidat, qui rejoint **el compañero** (le collègue) et touche **el sueldo** (le salaire). Le contraire, c’est **el paro** (le chômage)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["el colegio","l'école"],["el instituto","le lycée"],["el alumno","l'élève"],["el profesor","le professeur"],["la asignatura","la matière"],["los deberes","les devoirs"],["el examen","l'examen"],["la nota","la note"],["el título","le diplôme"],["la universidad","l'université"],["aprender","apprendre"],["estudiar","étudier"],["aprobar","réussir (un examen)"],["suspender","échouer"],["la competencia","la compétence"],["los conocimientos","les connaissances"],["la formación","la formation"],["el empleo","l'emploi"],["el trabajo","le travail"],["la carrera","la carrière"],["las prácticas","le stage"],["la entrevista","l'entretien"],["el compañero","le collègue"],["el sueldo","le salaire"],["contratar","embaucher"],["el paro","le chômage"]]}]},{h:"La empresa y la economía (STMG)",blocks:[{t:"p",c:"**La empresa** (l’entreprise) fait **los negocios** (les affaires) sur **el mercado** (le marché), où elle vise **la cuota de mercado** (la part de marché) face à **la competencia** (la concurrence). Elle vend **el producto** (le produit) à **el cliente** (le client) et au **consumidor** (consommateur), et achète à **el proveedor** (le fournisseur). **La venta** (la vente) dépend de **la oferta** (l’offre) et de **la demanda** (la demande) ; **la marca** (la marque) et **la estrategia** (la stratégie) soutiennent **el crecimiento** (la croissance)."},{t:"p",c:"Côté finances, **el volumen de negocio** (le chiffre d’affaires) et **los ingresos** (les revenus) doivent couvrir **el coste** (le coût) pour dégager **el beneficio** (le bénéfice) et non **la pérdida** (la perte). **El balance** (le bilan) et **la tesorería** (la trésorerie) renseignent sur sa santé. Pour financer **la inversión** (l’investissement) prévue dans **el presupuesto** (le budget), elle peut recourir à **el préstamo** (l’emprunt) ou à **el accionista** (l’actionnaire)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["la empresa","l'entreprise"],["los negocios","les affaires"],["el volumen de negocio","le chiffre d'affaires"],["el beneficio","le bénéfice"],["la pérdida","la perte"],["el balance","le bilan"],["la tesorería","la trésorerie"],["el coste","le coût"],["los ingresos","les revenus"],["el presupuesto","le budget"],["la inversión","l'investissement"],["el préstamo","l'emprunt"],["el accionista","l'actionnaire"],["el mercado","le marché"],["la cuota de mercado","la part de marché"],["el cliente","le client"],["el proveedor","le fournisseur"],["la marca","la marque"],["el crecimiento","la croissance"],["la estrategia","la stratégie"],["la competencia","la concurrence"],["el producto","le produit"],["la venta","la vente"],["la oferta","l'offre"],["la demanda","la demande"],["el consumidor","le consommateur"]]}]},{h:"Sociedad, memoria y política",blocks:[{t:"p",c:"Dans **la sociedad** (la société) démocratique, **el ciudadano** (le citoyen) a **el derecho** (le droit) de **votar** (voter) lors de **las elecciones** (les élections) qui désignent **el gobierno** (le gouvernement). **La ley** (la loi) défend **la igualdad** (l’égalité) et **la libertad** (la liberté), et combat **la desigualdad** (l’inégalité) et **la pobreza** (la pauvreté). **La inmigración** (l’immigration) et le contrôle de **la frontera** (la frontière) font débat ; les mécontentements s’expriment par **la manifestación** (la manifestation) ou **la huelga** (la grève), relayées par **los medios** (les médias) et **las noticias** (les informations)."},{t:"p",c:"En Espagne et en Amérique latine, **la memoria** (la mémoire) est un thème central : le passage de **la dictadura** (la dictature) à **la democracia** (la démocratie), le souvenir de **la guerra** (la guerre) et de **el exilio** (l’exil), la recherche de **la paz** (la paix) et la protection de **el patrimonio** (le patrimoine)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["la sociedad","la société"],["el gobierno","le gouvernement"],["las elecciones","les élections"],["votar","voter"],["el ciudadano","le citoyen"],["el derecho","le droit"],["la ley","la loi"],["la igualdad","l'égalité"],["la libertad","la liberté"],["la desigualdad","l'inégalité"],["la pobreza","la pauvreté"],["la inmigración","l'immigration"],["la frontera","la frontière"],["la manifestación","la manifestation"],["la dictadura","la dictature"],["la democracia","la démocratie"],["la memoria","la mémoire"],["el exilio","l'exil"],["el patrimonio","le patrimoine"],["la guerra","la guerre"],["la paz","la paix"],["los medios","les médias"],["las noticias","les informations"],["la huelga","la grève"]]}]},{h:"Medio ambiente y ciencia",blocks:[{t:"p",c:"Protéger **el medio ambiente** (l’environnement) est urgent face à **el cambio climático** (le changement climatique) et à **el calentamiento global** (le réchauffement climatique). **La contaminación** (la pollution) et **los residuos** (les déchets) menacent **la naturaleza** (la nature), **el bosque** (la forêt), **la biodiversidad** (la biodiversité) et chaque **especie** (espèce) de **el planeta** (la planète). Les catastrophes se multiplient : **la sequía** (la sécheresse), **la inundación** (l’inondation)."},{t:"p",c:"Pour **proteger** (protéger) la planète, il faut **reducir** (réduire) **la huella de carbono** (l’empreinte carbone), **reciclar** (recycler), cesser de **contaminar** (polluer), économiser chaque **recurso** (ressource) et développer **las energías renovables** (les énergies renouvelables) pour une **energía** plus **sostenible** (durable). **La ciencia** (la science), **la investigación** (la recherche) et chaque **descubrimiento** (découverte) y contribuent."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["el medio ambiente","l'environnement"],["el cambio climático","le changement climatique"],["el calentamiento global","le réchauffement climatique"],["la contaminación","la pollution"],["los residuos","les déchets"],["reciclar","recycler"],["las energías renovables","les énergies renouvelables"],["la huella de carbono","l'empreinte carbone"],["sostenible","durable"],["contaminar","polluer"],["la sequía","la sécheresse"],["la inundación","l'inondation"],["el bosque","la forêt"],["la naturaleza","la nature"],["proteger","protéger"],["reducir","réduire"],["la energía","l'énergie"],["el recurso","la ressource"],["la biodiversidad","la biodiversité"],["la investigación","la recherche"],["el descubrimiento","la découverte"],["la ciencia","la science"],["la especie","l'espèce"],["el planeta","la planète"]]}]},{h:"Tecnología e internet",blocks:[{t:"p",c:"**La tecnología** (la technologie) est partout : sur **el ordenador** (l’ordinateur), **el móvil** (le portable) ou tout autre **aparato** (appareil), on passe des heures devant **la pantalla** (l’écran). On est **en línea** (en ligne), sur **la red** (le réseau), **las redes sociales** (les réseaux sociaux), **la página web** (le site web) ou **la aplicación** (l’application). On aime **navegar** (naviguer), **descargar** (télécharger), **compartir** (partager) et **conectarse** (se connecter), et il faut **actualizar** (mettre à jour) **el programa** (le logiciel)."},{t:"p",c:"Chaque **usuario** (utilisateur) laisse **los datos** (les données) : protéger **la privacidad** (la vie privée) passe par **la contraseña** (le mot de passe) et **la ciberseguridad** (la cybersécurité). **La inteligencia artificial** (l’intelligence artificielle) transforme le monde **digital** (numérique), qui peut créer **la adicción** (la dépendance)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["la tecnología","la technologie"],["el ordenador","l'ordinateur"],["el móvil","le portable"],["la pantalla","l'écran"],["la red","le réseau"],["las redes sociales","les réseaux sociaux"],["la página web","le site web"],["la aplicación","l'application"],["los datos","les données"],["la privacidad","la vie privée"],["la contraseña","le mot de passe"],["descargar","télécharger"],["en línea","en ligne"],["el usuario","l'utilisateur"],["la inteligencia artificial","l'intelligence artificielle"],["el programa","le logiciel"],["el aparato","l'appareil"],["navegar","naviguer"],["la ciberseguridad","la cybersécurité"],["actualizar","mettre à jour"],["digital","numérique"],["la adicción","la dépendance"],["conectarse","se connecter"],["compartir","partager"]]}]},{h:"Verbos frecuentes",blocks:[{t:"p",c:"Deux verbes traduisent « être » : **ser** et **estar** ; deux traduisent « avoir » : **tener**, qui exprime la possession, et **haber**, qui sert d’auxiliaire. Les verbes les plus courants sont ensuite **hacer** (faire), **ir** (aller), **poder** (pouvoir), **querer** (vouloir, aimer), **saber** (savoir), **decir** (dire), **ver** (voir), **dar** (donner), **poner** (mettre), **salir** (sortir), **venir** (venir) et **llegar** (arriver)."},{t:"p",c:"Parmi les verbes réguliers, retiens les modèles **hablar** (parler), **comer** (manger) et **vivir** (vivre), ainsi que **trabajar** (travailler), **comprar** (acheter), **vender** (vendre), **terminar** (finir). Attention à **empezar** (commencer), **pensar** (penser) et **entender** (comprendre), dont le radical change au présent : *empiezo*, *pienso*, *entiendo*."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["ser","être (identité, caractère durable)"],["estar","être (état, lieu)"],["tener","avoir (possession)"],["haber","avoir (auxiliaire)"],["hacer","faire"],["ir","aller"],["poder","pouvoir"],["querer","vouloir, aimer"],["saber","savoir"],["decir","dire"],["ver","voir"],["dar","donner"],["poner","mettre"],["salir","sortir"],["venir","venir"],["llegar","arriver"],["hablar","parler"],["comer","manger"],["vivir","vivre"],["trabajar","travailler"],["comprar","acheter"],["vender","vendre"],["empezar","commencer"],["terminar","finir"],["pensar","penser"],["entender","comprendre"]]}]},{h:"Conectores y expresar la opinión",blocks:[{t:"p",c:"Pour organiser un texte, on enchaîne **primero** (d’abord), **luego** (ensuite), **después** (après) et **por fin** (enfin). On ajoute avec **además** (de plus), on s’oppose avec **sin embargo** (cependant), **en cambio** (en revanche) ou **mientras que** (tandis que), et on concède avec **aunque** (bien que). On explique avec **porque** (parce que), **es decir** (c’est-à-dire) et **de hecho** (en fait), on conclut une étape avec **por lo tanto** (donc), et on illustre avec **por ejemplo** (par exemple). Pour comparer : **por un lado** (d’une part)… **por otro lado** (d’autre part)."},{t:"p",c:"Pour donner son avis : **en mi opinión** (à mon avis), **creo que** (je pense que), **estoy de acuerdo** (je suis d’accord) ou **no estoy de acuerdo** (je ne suis pas d’accord), **es verdad que** (il est vrai que), et **según** (selon) pour citer une source. Pour finir : **en resumen** (en résumé) et **en conclusión** (en conclusion)."},{t:"table",h:"Vocabulaire à retenir",head:["Mot","Sens"],rows:[["primero","d'abord"],["luego","ensuite"],["después","après"],["por fin","enfin"],["además","de plus"],["sin embargo","cependant"],["por lo tanto","donc"],["porque","parce que"],["aunque","bien que"],["por un lado","d'une part"],["por otro lado","d'autre part"],["por ejemplo","par exemple"],["en mi opinión","à mon avis"],["creo que","je pense que"],["estoy de acuerdo","je suis d'accord"],["no estoy de acuerdo","je ne suis pas d'accord"],["en resumen","en résumé"],["en conclusión","en conclusion"],["es decir","c'est-à-dire"],["mientras que","tandis que"],["según","selon"],["de hecho","en fait"],["en cambio","en revanche"],["es verdad que","il est vrai que"]]}]}],essentiel:["Réviser le vocabulaire **par thème** et le voir en **contexte** (le dictionnaire intégré traduit aussi les phrases).","Vocabulaire **STMG** utile : la empresa (entreprise), el paro (chômage), el sueldo (salaire), el préstamo (emprunt), la cuota de mercado (part de marché).","Bien distinguer les **faux-amis** : *el paro* = le chômage (pas « le pari »), *sensible* = sensible ≠ *sensato* = sensé."],games:[{id:"lng-es-voc-daily-memory",type:"memory",title:"Memory — vida cotidiana",icon:"🧠",pairs:[{a:"la familia",b:"la famille"},{a:"el vecino",b:"le voisin"},{a:"la comida",b:"le repas"},{a:"la habitación",b:"la chambre"},{a:"el fin de semana",b:"le week-end"},{a:"el amigo",b:"l'ami"}]},{id:"lng-es-voc-empresa-qcm",type:"qcm",title:"QCM — la empresa",icon:"❓",questions:[{q:"« el paro » =",choices:["le chômage","le salaire","le marché","le client"],answer:0,explain:"el paro = le chômage."},{q:"« la empresa » =",choices:["l'entreprise","le produit","la vente","le patron"],answer:0,explain:"la empresa = l’entreprise."},{q:"« el préstamo » =",choices:["l'emprunt","le bénéfice","le budget","le prêt-à-porter"],answer:0,explain:"el préstamo = l’emprunt, le prêt."},{q:"« la cuota de mercado » =",choices:["la part de marché","le marché","la marque","la demande"],answer:0,explain:"la cuota de mercado = la part de marché."},{q:"« el proveedor » =",choices:["le fournisseur","le client","le concurrent","le vendeur"],answer:0,explain:"el proveedor = le fournisseur."}]},{id:"lng-es-voc-medio-assoc",type:"association",title:"Association — medio ambiente",icon:"🔗",pairs:[{left:"el cambio climático",right:"le changement climatique"},{left:"los residuos",right:"les déchets"},{left:"la sequía",right:"la sécheresse"},{left:"las energías renovables",right:"les énergies renouvelables"},{left:"el medio ambiente",right:"l'environnement"}]},{id:"lng-es-voc-verbos-memory",type:"memory",title:"Memory — verbes fréquents",icon:"🧠",pairs:[{a:"tener",b:"avoir"},{a:"hacer",b:"faire"},{a:"poder",b:"pouvoir"},{a:"querer",b:"vouloir"},{a:"saber",b:"savoir"},{a:"decir",b:"dire"}]}]},{id:"lng-es-verbs",name:"Espagnol — Verbes irréguliers",short:"Espagnol · verbes irréguliers",keywords:"verbes irréguliers espagnol presente indefinido ser tener hacer ir",intro:"🇪🇸 Entraîne-toi aux six verbes irréguliers espagnols du cours (présent « yo » et passé simple) : chaque partie sélectionne et mélange dix questions de cette banque.",cours:[{h:"Verbes irréguliers : racines e → ie, o → ue et passés irréguliers",blocks:[{t:"p",c:"Les verbes les plus irréguliers changent à la fois au présent et au passé simple. **Ser** donne *soy* au présent et *fue* au passé simple à la troisième personne ; **ir** donne *voy* et la même forme *fue*. **Tener** donne *tengo* et *tuvo* ; **hacer** donne *hago* et *hizo* ; **poder** donne *puedo* et *pudo* ; **decir** donne *digo* et *dijo*."},{t:"tip",c:"Beaucoup changent la **racine** (e→ie, o→ue) ou sont totalement irréguliers au passé simple."},{t:"table",h:"Verbes irréguliers à retenir",head:["Verbe (présent yo, indefinido él)","Sens"],rows:[["ser (soy, fue)","être"],["tener (tengo, tuvo)","avoir"],["hacer (hago, hizo)","faire"],["ir (voy, fue)","aller"],["poder (puedo, pudo)","pouvoir"],["decir (digo, dijo)","dire"]]}]}],games:[{id:"lng-es-verbs-gen",type:"verbs",title:"Verbes irréguliers — entraînement",icon:"🔤",count:10,questions:[{prompt:"Présent (yo) de ser (être) ?",answer:"soy",explain:"ser (soy, fue) — être"},{prompt:"Passé simple (él/ella) de ser (être) ?",answer:"fue",explain:"ser (soy, fue) — être"},{prompt:"Quel est l’infinitif dont le présent « yo » est « soy » ? (être)",answer:"ser",explain:"ser (soy, fue) — être"},{prompt:"Présent (yo) de tener (avoir) ?",answer:"tengo",explain:"tener (tengo, tuvo) — avoir"},{prompt:"Passé simple (él/ella) de tener (avoir) ?",answer:"tuvo",explain:"tener (tengo, tuvo) — avoir"},{prompt:"Quel est l’infinitif dont le présent « yo » est « tengo » ? (avoir)",answer:"tener",explain:"tener (tengo, tuvo) — avoir"},{prompt:"Présent (yo) de hacer (faire) ?",answer:"hago",explain:"hacer (hago, hizo) — faire"},{prompt:"Passé simple (él/ella) de hacer (faire) ?",answer:"hizo",explain:"hacer (hago, hizo) — faire"},{prompt:"Quel est l’infinitif dont le présent « yo » est « hago » ? (faire)",answer:"hacer",explain:"hacer (hago, hizo) — faire"},{prompt:"Présent (yo) de ir (aller) ?",answer:"voy",explain:"ir (voy, fue) — aller"},{prompt:"Passé simple (él/ella) de ir (aller) ?",answer:"fue",explain:"ir (voy, fue) — aller"},{prompt:"Quel est l’infinitif dont le présent « yo » est « voy » ? (aller)",answer:"ir",explain:"ir (voy, fue) — aller"},{prompt:"Présent (yo) de poder (pouvoir) ?",answer:"puedo",explain:"poder (puedo, pudo) — pouvoir"},{prompt:"Passé simple (él/ella) de poder (pouvoir) ?",answer:"pudo",explain:"poder (puedo, pudo) — pouvoir"},{prompt:"Quel est l’infinitif dont le présent « yo » est « puedo » ? (pouvoir)",answer:"poder",explain:"poder (puedo, pudo) — pouvoir"},{prompt:"Présent (yo) de decir (dire) ?",answer:"digo",explain:"decir (digo, dijo) — dire"},{prompt:"Passé simple (él/ella) de decir (dire) ?",answer:"dijo",explain:"decir (digo, dijo) — dire"},{prompt:"Quel est l’infinitif dont le présent « yo » est « digo » ? (dire)",answer:"decir",explain:"decir (digo, dijo) — dire"}]}]},{id:"lng-es-grammar-ex",name:"Espagnol — Grammaire (exercices)",short:"Espagnol · grammaire",keywords:"grammaire espagnole exercices ser estar por para el la muy mucho gustar présent",intro:"🇪🇸 Les règles de grammaire en exercices générés : ser/estar, por/para, articles, gustar, muy/mucho… De nouveaux items à chaque fois.",cours:[{h:"Règles clés : ser / estar, por / para, articles el / la, gustar",blocks:[{t:"list",c:["**ser** (identité) vs **estar** (état, lieu).","**por** (cause) vs **para** (but, destinataire).","Articles : **el / la** (attention : el problema, la mano).","Verbe **gustar** : me / te / le… + gusta(n)."]},{t:"p",c:"**Ser** exprime l’identité ou la profession : **yo soy profesor**. **Estar** exprime un état (**ella está cansada**) ou un lieu (**Madrid está en España**)."},{t:"p",c:"**Por** indique notamment la cause (**gracias por tu ayuda**). **Para** indique le destinataire (**este regalo es para ti**) ou le but (**estudio para aprobar**)."},{t:"p",c:"Les articles de certains noms doivent être mémorisés : **el problema**, **la mano**. Avec **gustar**, le pronom désigne la personne à qui quelque chose plaît : **a mí me gusta el fútbol**, **a ti te gustan los libros**."},{t:"tip",c:"Chaque partie mélange **dix questions sur les règles et exemples de ce cours**. Certaines questions peuvent revenir pour consolider tes acquis."}]}],games:[{id:"lng-es-grammar-gen",type:"grammar",title:"Grammaire — exercices variés",icon:"🧩",count:10,questions:[{prompt:"ser / estar : Yo ____ profesor.",answer:"soy",explain:"ser pour l’identité ou la profession."},{prompt:"ser / estar : Ella ____ cansada.",answer:"está",explain:"estar pour un état."},{prompt:"ser / estar : Madrid ____ en España.",answer:"está",explain:"estar pour un lieu."},{prompt:"por / para : Gracias ____ tu ayuda.",answer:"por",explain:"por pour la cause."},{prompt:"por / para : Este regalo es ____ ti.",answer:"para",explain:"para pour le destinataire."},{prompt:"por / para : Estudio ____ aprobar.",answer:"para",explain:"para pour le but."},{prompt:"Article : ____ problema.",answer:"el",explain:"Le cours donne l’exception el problema."},{prompt:"Article : ____ mano.",answer:"la",explain:"Le cours donne l’exception la mano."},{prompt:"Verbe gustar : A mí ____ gusta el fútbol.",answer:"me",explain:"me gusta : cela me plaît."},{prompt:"Verbe gustar : A ti ____ gustan los libros.",answer:"te",explain:"te gustan : ils te plaisent."}]}]},{id:"lng-es-comp",name:"Espagnol — Compréhension",short:"Espagnol · compréhension",keywords:"compréhension orale écrite écoute lecture niveau A2 B1 B2 audio texte questions correction",intro:"🇪🇸 Compréhensions orales (écoute) et écrites, classées par niveau. Choisis ton niveau, réponds aux questions, puis découvre la correction.",cours:[{h:"Niveau A2 — Débutant",blocks:[{t:"p",c:"Textes et dialogues **simples** (vie quotidienne). Idéal pour se lancer."}]},{h:"Niveau B1 — Intermédiaire",blocks:[{t:"p",c:"Récits et situations **plus longs** (travail, voyages, école)."}]},{h:"Niveau B2 — Avancé",blocks:[{t:"p",c:"Sujets **d’actualité et professionnels** (entreprise, société)."}]}],games:[{type:"comprehension",icon:"📖",id:"cmp-es-a2-read",lang:"es",listen:!1,level:"A2",title:"Lectura — Mi familia",topic:"Mi familia",text:"Me llamo Lucía y tengo dieciséis años. Vivo en Sevilla con mis padres y mi hermano pequeño. Mi padre es médico y mi madre trabaja en un banco. Los fines de semana comemos todos juntos y por la tarde paseamos por el parque. Me gusta mucho mi familia porque siempre me ayuda.",questions:[{q:"¿Cuántos años tiene Lucía?",choices:["14","16","18"],answer:1,explain:"“tengo dieciséis años”."},{q:"¿Dónde vive?",choices:["En Madrid","En Sevilla","En Valencia"],answer:1,explain:"“Vivo en Sevilla”."},{q:"¿Qué hace su madre?",choices:["Es médica","Trabaja en un banco","Es profesora"],answer:1,explain:"“mi madre trabaja en un banco”."},{q:"¿Qué hacen los fines de semana?",choices:["Comen juntos","Van al cine","Trabajan"],answer:0,explain:"“comemos todos juntos”."}]},{type:"comprehension",icon:"🎧",id:"cmp-es-a2-listen",lang:"es",listen:!0,level:"A2",title:"Escucha — En el restaurante",topic:"En el restaurante",text:"Buenas tardes. ¿Qué desea comer? De primero, una ensalada, por favor. Muy bien. ¿Y de segundo? Pollo con patatas. ¿Para beber? Agua, por favor. ¿Quiere postre? Sí, un helado de chocolate. Enseguida se lo traigo. Muchas gracias.",questions:[{q:"¿Qué pide de primero el cliente?",choices:["Una sopa","Una ensalada","Pasta"],answer:1,explain:"“una ensalada”."},{q:"¿Qué pide de segundo?",choices:["Pescado","Pollo con patatas","Carne"],answer:1,explain:"“Pollo con patatas”."},{q:"¿Qué quiere beber?",choices:["Vino","Agua","Zumo"],answer:1,explain:"“Agua, por favor”."},{q:"¿Qué postre pide?",choices:["Fruta","Helado de chocolate","Tarta"],answer:1,explain:"“un helado de chocolate”."}]},{type:"comprehension",icon:"📖",id:"cmp-es-b1-read",lang:"es",listen:!1,level:"B1",title:"Lectura — Un intercambio",topic:"Un intercambio escolar",text:"El año pasado, Marco participó en un intercambio con un instituto de Barcelona. Vivió dos semanas en casa de una familia española y asistió a clases en catalán y en castellano. Al principio le costó entender, pero poco a poco mejoró su nivel. Además, hizo nuevos amigos y descubrió la comida mediterránea. Cuando volvió a Francia, decidió seguir estudiando español para poder viajar por Latinoamérica algún día.",questions:[{q:"¿Dónde fue Marco de intercambio?",choices:["A Madrid","A Barcelona","A México"],answer:1,explain:"“un instituto de Barcelona”."},{q:"¿Cuánto tiempo se quedó?",choices:["Una semana","Dos semanas","Un mes"],answer:1,explain:"“Vivió dos semanas”."},{q:"¿Qué le costó al principio?",choices:["Hacer amigos","Entender","Comer"],answer:1,explain:"“le costó entender”."},{q:"¿Qué decidió al volver?",choices:["Dejar el español","Seguir estudiando español","Vivir en España"],answer:1,explain:"“decidió seguir estudiando español”."}]},{type:"comprehension",icon:"🎧",id:"cmp-es-b1-listen",lang:"es",listen:!0,level:"B1",title:"Escucha — De compras",topic:"De compras",text:"Hola, ¿en qué puedo ayudarle? Busco unos zapatos negros para el trabajo. ¿Qué número calza? El cuarenta y dos. Estos son muy cómodos y cuestan sesenta euros. ¿Puedo probármelos? Claro, aquí tiene. Me quedan bien, me los llevo. ¿Paga en efectivo o con tarjeta? Con tarjeta, gracias.",questions:[{q:"¿Qué busca el cliente?",choices:["Zapatos negros","Una camisa","Un bolso"],answer:0,explain:"“unos zapatos negros para el trabajo”."},{q:"¿Qué número calza?",choices:["40","42","44"],answer:1,explain:"“El cuarenta y dos”."},{q:"¿Cuánto cuestan?",choices:["16 €","60 €","66 €"],answer:1,explain:"“cuestan sesenta euros”."},{q:"¿Cómo paga?",choices:["En efectivo","Con tarjeta","Con cheque"],answer:1,explain:"“Con tarjeta, gracias”."}]},{type:"comprehension",icon:"📖",id:"cmp-es-b2-read",lang:"es",listen:!1,level:"B2",title:"Lectura — El comercio electrónico",topic:"El comercio electrónico",text:"El comercio electrónico ha transformado la manera de consumir. Hoy en día, muchos clientes prefieren comprar por internet porque pueden comparar precios y recibir los productos en casa. Sin embargo, este crecimiento plantea retos: la protección de los datos personales, el impacto medioambiental de las entregas y la competencia para las pequeñas tiendas del centro. Para sobrevivir, muchos comercios locales han creado su propia página web y ofrecen la recogida en tienda.",questions:[{q:"¿Por qué prefieren comprar por internet muchos clientes?",choices:["Es más caro","Pueden comparar precios y recibir en casa","Es más lento"],answer:1,explain:"“pueden comparar precios y recibir los productos en casa”."},{q:"¿Cuál es uno de los retos citados?",choices:["La protección de los datos","La falta de productos","El exceso de tiendas"],answer:0,explain:"“la protección de los datos personales”."},{q:"¿A quién hace competencia el comercio electrónico?",choices:["A los bancos","A las pequeñas tiendas del centro","A los transportes"],answer:1,explain:"“la competencia para las pequeñas tiendas”."},{q:"¿Qué hacen los comercios locales para sobrevivir?",choices:["Cerrar","Crear su web y ofrecer recogida en tienda","Bajar los sueldos"],answer:1,explain:"“han creado su propia página web y ofrecen la recogida en tienda”."}]},{type:"comprehension",icon:"🎧",id:"cmp-es-b2-listen",lang:"es",listen:!0,level:"B2",title:"Escucha — Entrevista de trabajo",topic:"Una entrevista de trabajo",text:"Gracias por venir. ¿Puede hablarme de su experiencia? Claro. Terminé mis estudios de gestión y realicé unas prácticas en una empresa de marketing durante seis meses. ¿Por qué quiere trabajar aquí? Admiro su empresa y creo que mis conocimientos digitales pueden ayudar a atraer a clientes jóvenes. ¿Cuál es su mayor defecto? A veces soy demasiado perfeccionista, pero estoy aprendiendo a organizar mejor mi tiempo. Muy bien, le llamaremos la semana que viene.",questions:[{q:"¿Qué estudió el candidato?",choices:["Derecho","Gestión","Medicina"],answer:1,explain:"“mis estudios de gestión”."},{q:"¿Cuánto duraron las prácticas?",choices:["Tres meses","Seis meses","Un año"],answer:1,explain:"“durante seis meses”."},{q:"¿Cómo puede ayudar a la empresa?",choices:["Con conocimientos digitales","Con más horas","Con un salario bajo"],answer:0,explain:"“mis conocimientos digitales pueden ayudar a atraer a clientes jóvenes”."},{q:"¿Cuál es su defecto?",choices:["Llega tarde","Es demasiado perfeccionista","Habla poco"],answer:1,explain:"“soy demasiado perfeccionista”."}]}]},{id:"lng-it-gram",name:"Italien — Grammaire et conjugaison",short:"Grammaire et conjugaison",keywords:["Grammaire et conjugaison","italien"],intro:"Des bases à l’argumentation : rappels guidés, formes utiles et exemples corrigés. Les axes culturels de Première et de Terminale sont dans des thèmes distincts ; cette grammaire sert de référence aux deux niveaux.",cours:[{h:"Prononciation, articles et accords",blocks:[{t:"p",c:"L’italien distingue les consonnes simples et doubles : pala (pelle) et palla (ballon) ne se prononcent pas de la même façon. Devant e ou i, c se prononce comme « tch » et g comme « dj » ; ch et gh maintiennent les sons durs : chi, spaghetti. L’accent écrit distingue notamment e (et) de è (est)."},{t:"p",c:"L’article défini dépend du genre, du nombre et du début du mot : il libro → i libri ; lo studente → gli studenti ; l’amico → gli amici ; la casa → le case. Lo s’emploie notamment devant s + consonne et z. L’article indéfini donne un libro, uno studente, una casa, un’amica. Un amico n’a pas d’apostrophe, car un est masculin."},{t:"p",c:"Les noms en -o ont souvent un pluriel en -i, ceux en -a un pluriel en -e ; un nom en -e passe généralement à -i : studente → studenti. L’adjectif s’accorde : una casa nuova, due case nuove. Ces régularités ont des exceptions : apprends le genre avec le nom."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["il libro","Le livre ; pluriel i libri."],["lo studente","L’élève ; pluriel gli studenti."],["è","Est, forme de essere, avec accent."],["e","Et, conjonction sans accent."]]}]},{h:"Le présent : être, avoir et verbes fréquents",blocks:[{t:"p",c:"Essere : sono, sei, è, siamo, siete, sono. Avere : ho, hai, ha, abbiamo, avete, hanno. Le sujet peut rester implicite grâce à la terminaison : sono italiana signifie « je suis italienne » selon le contexte ; ho diciassette anni signifie « j’ai dix-sept ans ». On garde le pronom pour lever une ambiguïté ou insister."},{t:"p",c:"Au présent, parlare donne parlo, parli, parla, parliamo, parlate, parlano ; prendere : prendo, prendi, prende, prendiamo, prendete, prendono ; dormire : dormo, dormi, dorme, dormiamo, dormite, dormono. Certains verbes en -ire prennent -isc- : capisco, capisci, capisce, capiamo, capite, capiscono."},{t:"p",c:"Andare donne vado, vai, va, andiamo, andate, vanno ; fare : faccio, fai, fa, facciamo, fate, fanno. Pour nier, place non devant le verbe : non capisco. Une question peut garder le même ordre : studi italiano? Avec un mot interrogatif : dove studi? (où étudies-tu ?) et perché studi? (pourquoi étudies-tu ?)."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Essere","Être : sono, sei, è, siamo, siete, sono."],["Avere","Avoir : ho, hai, ha, abbiamo, avete, hanno."],["Non","Négation placée avant le verbe."],["Capire","Comprendre : capisco, capiamo."]]}]},{h:"Raconter : passato prossimo et imperfetto",blocks:[{t:"p",c:"Le passato prossimo se forme avec avere ou essere au présent et un participe passé : ho parlato, ho ricevuto, ho dormito. Avec essere, le participe s’accorde avec le sujet : Maria è arrivata ; Marco e Luca sono partiti. Tous les verbes de mouvement ne prennent pas automatiquement essere : apprends l’auxiliaire de chaque verbe, par exemple ho viaggiato."},{t:"p",c:"Les participes fréquents comprennent fatto (fare), detto (dire), visto (vedere), scritto (scrivere), letto (leggere) et preso (prendere). Dans une phrase simple avec avere sans pronom objet antéposé, le participe reste inchangé : Maria ha scritto una lettera."},{t:"p",c:"L’imperfetto décrit un état, une habitude ou l’arrière-plan : parlavo, parlavi, parlava, parlavamo, parlavate, parlavano ; essere donne ero, eri, era, eravamo, eravate, erano. Da piccola leggevo molto : enfant, je lisais beaucoup. Mentre studiavo, è arrivato Luca oppose une action en cours à l’événement qui survient. La distance chronologique seule ne décide pas du choix du temps."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Passato prossimo","Auxiliaire au présent + participe passé pour présenter un événement accompli."],["Imperfetto","Temps des habitudes, descriptions et arrière-plans du passé."],["È arrivata","Est arrivée : accord féminin avec essere."],["Ho viaggiato","J’ai voyagé : auxiliaire avere."]]}]},{h:"Futur, conditionnel et projets",blocks:[{t:"p",c:"Le futur de parlare donne parlerò, parlerai, parlerà, parleremo, parlerete, parleranno. Pour un verbe régulier en -are, le a devient e dans le radical ; prendere donne prenderò et dormire dormirò. Quelques radicaux sont irréguliers : essere → sarò, avere → avrò, andare → andrò, fare → farò, venire → verrò."},{t:"p",c:"Le conditionnel utilise les terminaisons -ei, -esti, -ebbe, -emmo, -este, -ebbero : parlerei, parleresti, parlerebbe, parleremmo, parlereste, parlerebbero. Les radicaux irréguliers du futur servent aussi au conditionnel : sarei, avrei, andrei. Vorrei signifie « je voudrais » ; potrei signifie « je pourrais »."},{t:"p",c:"L’anno prossimo farò uno stage annonce un stage l’an prochain. Vorrei lavorare in Italia exprime un souhait sans présenter sa réalisation comme certaine. Pour une hypothèse réalisable, on peut employer se + présent, puis futur : se ho tempo, verrò. Ne calque pas le français « si j’aurais » : l’hypothèse irréelle demande une autre construction."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Futuro","Temps pour annoncer notamment un événement à venir : parlerò."],["Condizionale","Mode du souhait, de la politesse ou d’une éventualité : parlerei."],["Vorrei","Je voudrais, forme polie de volere."],["Se ho tempo, verrò","Si j’ai le temps, je viendrai : hypothèse réalisable."]]}]},{h:"Pronoms, prépositions et comparaison",blocks:[{t:"p",c:"Les pronoms compléments directs lo, la, li, le remplacent une personne ou une chose sans préposition : compro il libro → lo compro ; vedo Maria → la vedo. Les pronoms indirects gli (à lui) et le (à elle) correspondent à un complément introduit par a : telefono a Marco → gli telefono. Devant l’infinitif, un pronom peut être attaché : voglio comprarlo."},{t:"p",c:"Les prépositions se choisissent avec leur construction : a Roma, in Italia, da un amico, di Roma. Avec un article, certaines fusionnent : a + il → al ; di + il → del ; in + il → nel. Sono di Roma indique l’origine ; vado a Roma la destination."},{t:"p",c:"La comparaison entre deux personnes ou objets peut employer più… di ou meno… di : questo prodotto è più caro di quello. L’égalité se dit aussi… come : è interessante come l’altro. Le superlatif relatif inclut l’article : il più caro. Avec piacere, la chose aimée est sujet : mi piace il libro, mi piacciono i libri."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Lo compro","Je l’achète : lo remplace un objet masculin singulier."],["Gli telefono","Je lui téléphone : gli renvoie ici à Marco."],["A Roma / in Italia","Prépositions usuelles pour la ville et le pays."],["Mi piacciono i libri","J’aime les livres : sujet pluriel, verbe pluriel."]]}]},{h:"Argumenter : subjonctif, hypothèse et discours rapporté",blocks:[{t:"p",c:"Pour structurer un avis, utilise secondo me (à mon avis), perché (parce que), tuttavia (cependant) et quindi (donc). Après penso che exprimant une opinion, l’italien soigné emploie normalement le congiuntivo : penso che sia utile. Essere au congiuntivo présent donne sia, sia, sia, siamo, siate, siano ; avere : abbia, abbia, abbia, abbiamo, abbiate, abbiano."},{t:"p",c:"Une hypothèse peu probable ou irréelle au présent peut se construire avec se + congiuntivo imperfetto, puis conditionnel présent : se avessi tempo, studierei di più (si j’avais le temps, j’étudierais davantage). Se fossi il direttore, cambierei il progetto : si j’étais le directeur, je changerais le projet. Ne transforme pas cette règle en interdiction générale de tout futur après se : se ho tempo, verrò reste correct."},{t:"p",c:"Pour rapporter une information, distingue ce qui est certain de ce qui est affirmé par une source : il giornale afferma che… signifie « le journal affirme que… ». Reformule sans attribuer l’opinion à tout un pays. Une argumentation solide cite un exemple précis, explique sa portée et reconnaît une limite : tuttavia, il costo rimane elevato (cependant, le coût reste élevé)."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Congiuntivo","Mode notamment employé après une opinion : penso che sia utile."],["Se avessi tempo, studierei","Hypothèse : subjonctif imparfait puis conditionnel présent."],["Tuttavia","Cependant : introduit une réserve ou une opposition."],["Quindi","Donc : introduit une conséquence."]]}]}],games:[{id:"lng-it-gram-s1-qcm",type:"qcm",title:"Prononciation, articles et accords",icon:"❓",questions:[{q:"Quel groupe signifie « les élèves » ?",choices:["gli studenti","lo studenti","i studente"],answer:0,explain:"Lo studente devient gli studenti."},{q:"Complète : due case…",choices:["nuove","nuovo","nuova"],answer:0,explain:"Case est féminin pluriel : nuove."},{q:"Quelle forme signifie « est » ?",choices:["è","e","il"],answer:0,explain:"È porte un accent ; e signifie et."}],sectionOnly:!0},{id:"lng-it-gram-s2-qcm",type:"qcm",title:"Le présent : être, avoir et verbes fréquents",icon:"❓",questions:[{q:"Complète : noi… italiano.",choices:["parliamo","parlate","parlano"],answer:0,explain:"Noi correspond à parliamo."},{q:"Comment dire « je ne comprends pas » ?",choices:["Non capisco.","Capisco non.","Non capiamo."],answer:0,explain:"Non se place avant capisco."},{q:"Complète : io… diciassette anni.",choices:["ho","sono","ha"],answer:0,explain:"L’âge s’exprime avec avere : ho."}],sectionOnly:!0},{id:"lng-it-gram-s3-qcm",type:"qcm",title:"Raconter : passato prossimo et imperfetto",icon:"❓",questions:[{q:"Maria… ieri. Choisis la forme correcte.",choices:["è arrivata","ha arrivato","è arrivato"],answer:0,explain:"Arrivare se conjugue ici avec essere et le participe s’accorde avec Maria."},{q:"Pour une habitude : Da piccola… molto.",choices:["leggevo","letto","leggere"],answer:0,explain:"Leggevo est l’imperfetto utilisé pour l’habitude."},{q:"Quel participe appartient à scrivere ?",choices:["scritto","detto","preso"],answer:0,explain:"Scrivere → scritto ; dire → detto ; prendere → preso."}],sectionOnly:!0},{id:"lng-it-gram-s4-qcm",type:"qcm",title:"Futur, conditionnel et projets",icon:"❓",questions:[{q:"Quel énoncé formule un souhait poli ?",choices:["Vorrei lavorare in Italia.","Lavorerò in Italia.","Lavoro in Italia."],answer:0,explain:"Vorrei exprime ici le souhait."},{q:"Quel est le futur de fare à la première personne ?",choices:["farò","farei","faccio"],answer:0,explain:"Farò est le futur ; farei le conditionnel ; faccio le présent."},{q:"Complète : se ho tempo,…",choices:["verrò","venuto","venire"],answer:0,explain:"Le futur verrò convient à cette hypothèse réalisable."}],sectionOnly:!0},{id:"lng-it-gram-s5-qcm",type:"qcm",title:"Pronoms, prépositions et comparaison",icon:"❓",questions:[{q:"Remplace il libro : compro il libro →…",choices:["lo compro","gli compro","le compro"],answer:0,explain:"Il libro est complément direct masculin singulier : lo."},{q:"Quelle construction est correcte ?",choices:["vado a Roma","vado in Roma","vado di Roma"],answer:0,explain:"La destination avec Roma s’exprime par a Roma."},{q:"Complète : mi… i libri.",choices:["piacciono","piace","piaci"],answer:0,explain:"I libri est le sujet pluriel : piacciono."}],sectionOnly:!0},{id:"lng-it-gram-s6-qcm",type:"qcm",title:"Argumenter : subjonctif, hypothèse et discours rapporté",icon:"❓",questions:[{q:"Complète : penso che… utile.",choices:["sia","è","sarò"],answer:0,explain:"Dans ce registre soigné, penso che appelle ici le congiuntivo sia."},{q:"Complète : se avessi tempo,… di più.",choices:["studierei","studierò","studio"],answer:0,explain:"La proposition principale prend le conditionnel studierei."},{q:"Quel connecteur introduit une réserve ?",choices:["tuttavia","quindi","perché"],answer:0,explain:"Tuttavia signifie cependant."}],sectionOnly:!0}]},{id:"lng-ar-gram",name:"Arabe — Écriture et grammaire de l’arabe standard",short:"Écriture et grammaire de l’arabe standard",keywords:["Écriture et grammaire de l’arabe standard","arabe"],intro:"Référence progressive pour lire et construire des phrases en arabe standard moderne. Les dialectes ont des usages et des formes qui peuvent différer ; ces cours ne les présentent pas comme des erreurs. Les explications restent en français, les exemples en écriture arabe.",cours:[{h:"Lire l’écriture et se présenter",blocks:[{t:"p",c:"L’arabe s’écrit de droite à gauche. Ses lettres changent de forme selon leur position ; ا د ذ ر ز و ne se lient pas à la lettre suivante à gauche. Les voyelles brèves peuvent être notées par des signes : fatḥa ـَ (a), kasra ـِ (i), ḍamma ـُ (u). Les lettres ا و ي servent notamment à noter des voyelles longues. Le sukūn ـْ marque l’absence de voyelle et la shadda ـّ une consonne redoublée."},{t:"p",c:"Repère les 28 lettres dans l’ordre : ا ب ت ث ج ح خ د ذ ر ز س ش ص ض ط ظ ع غ ف ق ك ل م ن ه و ي. Plusieurs lettres partagent une forme et se distinguent par leurs points : ب، ت، ث ; ج، ح، خ. Recopie-les en observant le nombre et la position des points, puis compare leur forme dans un mot. Ne confonds pas ة, souvent finale féminine, avec ه. Les chiffres et les segments latins gardent leur propre sens de lecture dans une phrase arabe."},{t:"p",c:"Les textes ordinaires omettent souvent les voyelles brèves : le contexte aide à lire. La translittération est une aide provisoire : marḥaban (مرحبا) signifie bonjour ; shukran (شكرا), merci. ʿ représente ع et ḥ représente ح, distinct de ه. Il faut écouter un locuteur ou un enregistrement pour travailler ces sons ; un exemple écrit ne constitue pas un exercice d’écoute."},{t:"p",c:"Pour se présenter : اسمي ليلى (ismī Laylā), « je m’appelle Layla » ; أنا طالب (anā ṭālib), « je suis étudiant » ; أنا طالبة (anā ṭāliba), « je suis étudiante ». Au présent, une phrase de ce type n’emploie pas de verbe être exprimé. من أين أنت؟ demande « d’où viens-tu ? ». La forme vocalisée de أنت varie selon le destinataire : anta au masculin, anti au féminin."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Fatḥa","Signe de la voyelle brève a : ـَ."],["Shadda","Signe de redoublement de la consonne : ـّ."],["مرحبا","Bonjour ; translittération indicative marḥaban."],["اسمي","Mon nom est / je m’appelle : ismī."]]}]},{h:"Article, genre, adjectif et possession",blocks:[{t:"p",c:"L’article défini ال s’attache au nom : كتاب (un livre) → الكتاب (le livre). Devant une lettre solaire, le l de l’article s’assimile à la consonne suivante dans la prononciation : الشمس (ash-shams, le soleil). Devant une lettre lunaire, il se prononce : القمر (al-qamar, la lune). L’écriture de l’article reste ال dans les deux cas."},{t:"p",c:"L’adjectif épithète suit le nom et s’accorde notamment en genre et en détermination : كتاب جديد (un livre nouveau), الكتاب الجديد (le livre nouveau), مدرسة جديدة (une école nouvelle). En revanche, الكتاب جديد signifie « le livre est nouveau » : le nom est défini et l’attribut est ici indéfini. La tāʾ marbūṭa ة marque souvent un féminin mais n’en constitue pas une règle sans exception."},{t:"p",c:"L’annexion relie deux noms : كتاب الطالب signifie « le livre de l’élève ». Dans cette construction, le premier nom ne prend pas ال ; la détermination vient du second. Un suffixe peut marquer le possesseur : كتابي (mon livre), كتابه (son livre à lui), كتابها (son livre à elle). Ces exemples doivent être appris avec le sens du suffixe, sans ajouter un article devant كتابي."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["ال","Article défini attaché au nom."],["الكتاب الجديد","Le livre nouveau : adjectif épithète également défini."],["الكتاب جديد","Le livre est nouveau : phrase nominale."],["كتابي","Mon livre : suffixe possessif ـي."]]}]},{h:"Pronoms et conjugaison : accompli et inaccompli",blocks:[{t:"p",c:"Les pronoms personnels utiles sont أنا (je), نحن (nous), أنت (tu), هو (il), هي (elle), أنتم (vous masculin pluriel ou groupe mixte), هم (ils). L’arabe distingue aussi le duel et des formes féminines ; le contexte et la vocalisation permettent notamment de distinguer anta (tu masculin) et anti (tu féminin)."},{t:"p",c:"L’accompli présente généralement un procès accompli, souvent au passé. Avec كتب, « écrire » : كَتَبْتُ (katabtu, j’ai écrit), كَتَبْتَ (katabta, tu masculin as écrit), كَتَبْتِ (katabti, tu féminin as écrit), كَتَبَ (kataba, il a écrit), كَتَبَتْ (katabat, elle a écrit), كَتَبْنَا (katabnā, nous avons écrit). Sans voyelles, plusieurs formes s’écrivent كتبت : ne devine pas le sujet sans contexte."},{t:"p",c:"L’inaccompli sert notamment au présent : أَكْتُبُ (aktubu, j’écris), يَكْتُبُ (yaktubu, il écrit), تَكْتُبُ (taktubu, elle écrit ou tu masculin écris selon le contexte), نَكْتُبُ (naktubu, nous écrivons). Pour annoncer l’avenir, on peut utiliser سـ ou سوف devant l’inaccompli : سأكتب / سوف أكتب (j’écrirai). Les catégories accompli/inaccompli ne se superposent pas mécaniquement aux temps français."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Accompli","Forme présentant notamment un procès accompli : كَتَبَ, il a écrit."],["Inaccompli","Forme servant notamment au présent : يَكْتُبُ, il écrit."],["نحن","Nous."],["سأكتب","J’écrirai : سـ + inaccompli."]]}]},{h:"Nier, interroger et situer",blocks:[{t:"p",c:"La négation لا devant l’inaccompli peut nier une action présente ou habituelle : لا أعمل اليوم signifie « je ne travaille pas aujourd’hui ». Pour le passé, لم est suivi d’un inaccompli apocopé : لم أكتبْ (je n’ai pas écrit). Pour le futur, لن est suivi d’un inaccompli au subjonctif : لن أكتبَ (je n’écrirai pas). Ce sont des constructions de l’arabe standard, à ne pas confondre avec les négations dialectales."},{t:"p",c:"Une question fermée peut commencer par هل : هل تعمل اليوم؟ (travailles-tu aujourd’hui ?). Les mots interrogatifs comprennent من (qui ?), ماذا (quoi ?), أين (où ?), متى (quand ?), لماذا (pourquoi ?) et كيف (comment ?). هل n’est pas nécessaire devant أين : أين المدرسة؟ signifie « où est l’école ? »."},{t:"p",c:"Les prépositions في (dans/à), من (de/depuis), إلى (vers/à), مع (avec) précisent les rapports : أنا في المدرسة (je suis à l’école), أذهب إلى المدرسة (je vais à l’école). عندي كتاب signifie « j’ai un livre », littéralement un livre est auprès de moi. Pour une négation nominale : لست طالبا (je ne suis pas étudiant) emploie une forme de ليس."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["لا أعمل","Je ne travaille pas : négation au présent."],["لم أكتبْ","Je n’ai pas écrit : لم + inaccompli apocopé."],["لن أكتبَ","Je n’écrirai pas : لن + inaccompli au subjonctif."],["أين","Où ?"]]}]},{h:"Pluriels, accord et phrases complexes",blocks:[{t:"p",c:"L’arabe possède des pluriels réguliers et des pluriels internes, dits brisés : كتاب → كتب (livre → livres), طالب → طلاب (étudiant → étudiants). Un pluriel féminin régulier se forme souvent en ـات : شركة → شركات (entreprise → entreprises). Apprends le pluriel avec chaque nom plutôt que d’appliquer une terminaison unique à tous les mots."},{t:"p",c:"Un pluriel non humain prend généralement un accord au féminin singulier : الكتب جديدة signifie « les livres sont nouveaux ». Pour un groupe humain masculin pluriel : الطلاب الجدد (les nouveaux étudiants). Ne généralise donc pas l’accord féminin singulier aux personnes."},{t:"p",c:"Pour relier des propositions, utilise و (et), لكن (mais), لأن (parce que), لذلك (c’est pourquoi) et الذي / التي (qui/que au masculin/féminin singulier). الشركة التي تنتج الكتب كبيرة signifie « l’entreprise qui produit les livres est grande ». La relative suit un antécédent défini et son relatif s’accorde avec lui. Une phrase organisée indique la cause puis la conséquence sans les confondre."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["جمع","Pluriel ; il peut être régulier ou interne."],["الكتب جديدة","Les livres sont nouveaux : accord féminin singulier avec un pluriel non humain."],["لأن","Parce que : introduit une cause."],["لذلك","C’est pourquoi : introduit une conséquence."]]}]},{h:"Décrire le passé et défendre un point de vue",blocks:[{t:"p",c:"كان permet de situer une phrase nominale au passé : كان الجو جميلا (il faisait beau). Avec un inaccompli, il peut présenter une activité habituelle ou en cours dans le passé : كنت أعمل في مكتبة (je travaillais dans une bibliothèque). Le contexte permet de préciser s’il s’agit d’une habitude ou d’une action en cours."},{t:"p",c:"Pour comparer : هذا المنتج أفضل من ذلك المنتج signifie « ce produit est meilleur que cet autre produit ». أفضل من exprime ici « meilleur que ». Pour argumenter : في رأيي (à mon avis), أعتقد أن (je pense que), من جهة (d’un côté), من جهة أخرى (d’un autre côté), مثلا (par exemple), في الختام (en conclusion)."},{t:"p",c:"Exemple : في رأيي، هذا المشروع مفيد لأنه يحمي البيئة، لكن تكلفته مرتفعة. Le projet est jugé utile parce qu’il protège l’environnement, mais son coût est élevé. Identifie l’avis, sa justification et sa limite. Pour citer une source, selon le texte se dit حسب النص ; une interprétation personnelle ne doit pas être présentée comme une citation."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["كان + inaccompli","Construction pour une activité habituelle ou en cours dans le passé."],["في رأيي","À mon avis."],["أفضل من","Meilleur que, dans la comparaison proposée."],["حسب النص","Selon le texte : attribue une information à sa source."]]}]}],games:[{id:"lng-ar-gram-s1-qcm",type:"qcm",title:"Lire l’écriture et se présenter",icon:"❓",questions:[{q:"Quel signe marque le redoublement d’une consonne ?",choices:["Shadda","Fatḥa","Sukūn"],answer:0,explain:"La shadda marque une consonne redoublée."},{q:"Que signifie اسمي ليلى ?",choices:["Je m’appelle Layla.","Merci, Layla.","D’où viens-tu, Layla ?"],answer:0,explain:"Ismī signifie mon nom est."},{q:"Dans أنا طالبة au présent, le verbe être est…",choices:["non exprimé","obligatoirement écrit","au passé"],answer:0,explain:"La phrase nominale ne comporte pas de verbe être exprimé au présent."}],sectionOnly:!0},{id:"lng-ar-gram-s2-qcm",type:"qcm",title:"Article, genre, adjectif et possession",icon:"❓",questions:[{q:"Quelle expression signifie « le livre est nouveau » ?",choices:["الكتاب جديد","الكتاب الجديد","كتاب الطالب"],answer:0,explain:"L’adjectif indéfini جديد est ici attribut du nom défini."},{q:"Comment dire « mon livre » ?",choices:["كتابي","كتابه","كتابها"],answer:0,explain:"Le suffixe ـي correspond à mon."},{q:"Dans كتاب الطالب, le premier nom porte-t-il ال ?",choices:["Non.","Oui, toujours.","Seulement devant une lettre solaire."],answer:0,explain:"Le premier terme de cette annexion ne prend pas l’article."}],sectionOnly:!0},{id:"lng-ar-gram-s3-qcm",type:"qcm",title:"Pronoms et conjugaison : accompli et inaccompli",icon:"❓",questions:[{q:"Quelle forme vocalisée signifie « j’ai écrit » ?",choices:["كَتَبْتُ","كَتَبَ","كَتَبَتْ"],answer:0,explain:"La terminaison ـتُ indique ici la première personne."},{q:"Que signifie نَكْتُبُ ?",choices:["Nous écrivons.","Il écrit.","Elle a écrit."],answer:0,explain:"Le préfixe نـ indique ici nous."},{q:"Quelle forme annonce l’avenir ?",choices:["سأكتب","كَتَبَ","كَتَبْنَا"],answer:0,explain:"سـ devant l’inaccompli annonce ici le futur."}],sectionOnly:!0},{id:"lng-ar-gram-s4-qcm",type:"qcm",title:"Nier, interroger et situer",icon:"❓",questions:[{q:"Quelle phrase nie une action future ?",choices:["لن أكتبَ","لم أكتبْ","أين المدرسة؟"],answer:0,explain:"لن porte ici sur l’avenir."},{q:"Quel mot demande un lieu ?",choices:["أين","متى","لماذا"],answer:0,explain:"أين signifie où ; متى quand ; لماذا pourquoi."},{q:"Quelle préposition introduit la destination dans أذهب… المدرسة ?",choices:["إلى","مع","من"],answer:0,explain:"إلى marque la destination."}],sectionOnly:!0},{id:"lng-ar-gram-s5-qcm",type:"qcm",title:"Pluriels, accord et phrases complexes",icon:"❓",questions:[{q:"Complète : الكتب…",choices:["جديدة","جديدون","جديدات"],answer:0,explain:"Le pluriel non humain الكتب prend ici un attribut au féminin singulier."},{q:"Quel connecteur introduit une cause ?",choices:["لأن","لذلك","لكن"],answer:0,explain:"لأن signifie parce que."},{q:"Quel est le pluriel de شركة donné dans le cours ?",choices:["شركات","كتب","طلاب"],answer:0,explain:"شركة devient شركات ; les autres pluriels concernent livre et étudiant."}],sectionOnly:!0},{id:"lng-ar-gram-s6-qcm",type:"qcm",title:"Décrire le passé et défendre un point de vue",icon:"❓",questions:[{q:"Que signifie في رأيي ?",choices:["À mon avis.","Selon le texte.","En conclusion."],answer:0,explain:"في رأيي introduit un point de vue personnel."},{q:"Dans l’exemple, quelle réserve est exprimée sur le projet ?",choices:["Son coût est élevé.","Il ne protège pas l’environnement.","Il n’a aucune utilité."],answer:0,explain:"لكن تكلفته مرتفعة signifie mais son coût est élevé."},{q:"Quelle expression attribue une information au texte ?",choices:["حسب النص","في رأيي","مثلا"],answer:0,explain:"حسب النص signifie selon le texte."}],sectionOnly:!0}]},{id:"lng-it-voc",name:"Italien — Vocabulaire en contexte et ETLV",short:"Vocabulaire en contexte et ETLV",keywords:["Vocabulaire en contexte et ETLV","italien"],intro:"Mots utiles pour la vie quotidienne, les études et les organisations. Les cas sont des supports pédagogiques fictifs, pas des statistiques sur un pays.",cours:[{h:"Vie quotidienne, études et mobilité",blocks:[{t:"p",c:"La famiglia est la famille, la scuola l’école, lo studente l’élève, l’insegnante l’enseignant. Gli studi désigne les études, tandis que lo stage ou il tirocinio désignent un stage. Pour se déplacer : il treno (train), la stazione (gare), il viaggio (voyage). Un biglietto est un billet, pas une facture."},{t:"p",c:"Mi chiamo Sara, studio economia e cerco un tirocinio a Torino : je m’appelle Sara, j’étudie l’économie et je cherche un stage à Turin. Pour écrire une demande polie : Buongiorno, vorrei ricevere informazioni sul tirocinio. Termine par Cordiali saluti. Adapte tu ou Lei au destinataire, sans mélanger les registres."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Tirocinio","Stage en milieu professionnel."],["Biglietto","Billet, notamment de transport."],["Cordiali saluti","Formule de clôture d’un message professionnel."]]}]},{h:"Entreprise, économie et ETLV",blocks:[{t:"p",c:"L’azienda ou l’impresa est l’entreprise ; un dipendente est un salarié, il cliente un client, il fornitore un fournisseur. Il fatturato est le chiffre d’affaires, il costo un coût et l’utile un bénéfice. Ne confonds pas chiffre d’affaires et bénéfice : le bénéfice tient compte des charges. Una fattura signifie une facture ; una fabbrica, une usine."},{t:"p",c:"Cas fictif : L’impresa produce biciclette e vende i suoi prodotti ai negozi. Il fatturato cresce, ma aumentano anche i costi. L’entreprise fabrique des vélos et les vend aux magasins. Son chiffre d’affaires augmente, mais ses coûts aussi : la hausse de son bénéfice n’est donc pas démontrée. À l’oral ETLV, présente l’activité, les parties prenantes et un indicateur, puis explique une limite."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Fatturato","Chiffre d’affaires, distinct du bénéfice."],["Utile","Bénéfice."],["Dipendente","Salarié."],["Fattura","Facture."]]}]},{h:"Numérique, environnement et opinion",blocks:[{t:"p",c:"La rete est le réseau ou Internet selon le contexte ; i dati personali sont les données personnelles, una fonte une source, una notizia une nouvelle. Una notizia falsa est une fausse information : un grand nombre de partages n’en prouve pas la fiabilité. Vérifie l’auteur, la date et les preuves avant de relayer."},{t:"p",c:"L’ambiente est l’environnement, i rifiuti les déchets, il riciclo le recyclage et l’energia rinnovabile l’énergie renouvelable. Ridurre i rifiuti signifie réduire les déchets. Possiamo ridurre i rifiuti, tuttavia dobbiamo cambiare le nostre abitudini : nous pouvons réduire les déchets, cependant nous devons changer nos habitudes. Une proposition devient convaincante quand on en précise l’action, l’effet attendu et la limite."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Dati personali","Données personnelles."],["Fonte","Source d’une information."],["Rifiuti","Déchets."],["Riciclo","Recyclage."]]}]}],games:[{id:"lng-it-voc-s1-qcm",type:"qcm",title:"Vie quotidienne, études et mobilité",icon:"❓",questions:[{q:"Quel mot désigne un stage ?",choices:["tirocinio","biglietto","stazione"],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."},{q:"Quelle formule termine un courriel professionnel ?",choices:["Cordiali saluti","Mi chiamo","Il treno"],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."}],sectionOnly:!0},{id:"lng-it-voc-s2-qcm",type:"qcm",title:"Entreprise, économie et ETLV",icon:"❓",questions:[{q:"Quel mot correspond au chiffre d’affaires ?",choices:["fatturato","utile","costo"],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."},{q:"Que peut-on conclure de ce cas ?",choices:["Le chiffre d’affaires et les coûts augmentent.","Le bénéfice augmente nécessairement.","L’entreprise ne vend rien."],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."}],sectionOnly:!0},{id:"lng-it-voc-s3-qcm",type:"qcm",title:"Numérique, environnement et opinion",icon:"❓",questions:[{q:"Que signifie i dati personali ?",choices:["Les données personnelles.","Les déchets.","Les sources."],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."},{q:"Quelle expression signifie réduire les déchets ?",choices:["ridurre i rifiuti","verificare una fonte","condividere una notizia"],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."}],sectionOnly:!0}]},{id:"lng-ar-voc",name:"Arabe — Vocabulaire en contexte et ETLV",short:"Vocabulaire en contexte et ETLV",keywords:["Vocabulaire en contexte et ETLV","arabe"],intro:"Mots utiles pour la vie quotidienne, les études et les organisations. Les cas sont des supports pédagogiques fictifs, pas des statistiques sur un pays.",cours:[{h:"Vie quotidienne, études et mobilité",blocks:[{t:"p",c:"La famille se dit الأسرة, l’école المدرسة, l’université الجامعة et l’étudiant الطالب (الطالبة au féminin). Le travail est العمل et le voyage السفر. Le train se dit القطار, la gare المحطة et le billet التذكرة. Les noms appris avec leur article peuvent le perdre selon la construction."},{t:"p",c:"Texte d’application : اسمي سلمى. أدرس في الجامعة وأذهب إلى المحطة بالحافلة. Salma se présente, dit qu’elle étudie à l’université et qu’elle va à la gare en bus. بالحافلة signifie en bus. Pour demander poliment : من فضلك، أين المحطة؟ (s’il vous plaît, où est la gare ?). Pour remercier : شكرا. Ces formulations sont en arabe standard."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["الجامعة","L’université."],["المحطة","La gare / la station."],["التذكرة","Le billet."],["من فضلك","S’il te plaît / s’il vous plaît, selon le destinataire."]]}]},{h:"Entreprise, économie et ETLV",blocks:[{t:"p",c:"L’entreprise se dit الشركة, le salarié الموظف, le client العميل et le fournisseur المورد. Le produit est المنتج, le prix السعر, le coût التكلفة et le bénéfice الربح. Une facture est فاتورة et une usine مصنع. Un chiffre de ventes élevé ne permet pas, à lui seul, de conclure à un bénéfice élevé : il faut prendre les charges en compte."},{t:"p",c:"Cas fictif : تنتج الشركة ملابس وتبيعها في متاجر محلية. ارتفعت المبيعات، لكن التكاليف ارتفعت أيضا. L’entreprise produit des vêtements et les vend dans des magasins locaux. Les ventes ont augmenté, mais les coûts aussi. Pour présenter une organisation en ETLV, précise son activité, ses clients et un enjeu, puis distingue les résultats observés de ton avis."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["الشركة","L’entreprise."],["العميل","Le client."],["التكلفة","Le coût."],["الربح","Le bénéfice."]]}]},{h:"Information, environnement et argumentation",blocks:[{t:"p",c:"Les médias se disent وسائل الإعلام, la source المصدر et les données personnelles البيانات الشخصية. Vérifier une information se dit التحقق من المعلومات. Une publication partagée n’est pas forcément vraie : distingue l’auteur du message, l’auteur de la photographie et le site qui la relaie."},{t:"p",c:"L’environnement se dit البيئة, l’eau الماء, les déchets النفايات et l’énergie renouvelable الطاقة المتجددة. Réduire la consommation d’eau : تقليل استهلاك الماء. Exemple : يجب حماية البيئة وتقليل النفايات (il faut protéger l’environnement et réduire les déchets). Pour nuancer : هذا الحل مفيد، لكنه مكلف (cette solution est utile, mais elle est coûteuse). Le mot لكن introduit la réserve."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["المصدر","La source."],["البيانات الشخصية","Les données personnelles."],["البيئة","L’environnement."],["الطاقة المتجددة","L’énergie renouvelable."]]}]}],games:[{id:"lng-ar-voc-s1-qcm",type:"qcm",title:"Vie quotidienne, études et mobilité",icon:"❓",questions:[{q:"Où Salma étudie-t-elle dans le texte ?",choices:["À l’université.","À la gare.","Dans le train."],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."},{q:"Que signifie التذكرة ?",choices:["Le billet.","La famille.","Le travail."],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."}],sectionOnly:!0},{id:"lng-ar-voc-s2-qcm",type:"qcm",title:"Entreprise, économie et ETLV",icon:"❓",questions:[{q:"Quel mot signifie le bénéfice ?",choices:["الربح","التكلفة","السعر"],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."},{q:"Que dit le cas sur les coûts ?",choices:["Ils ont augmenté aussi.","Ils ont disparu.","Ils sont toujours inconnus dans le texte."],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."}],sectionOnly:!0},{id:"lng-ar-voc-s3-qcm",type:"qcm",title:"Information, environnement et argumentation",icon:"❓",questions:[{q:"Que signifie البيانات الشخصية ?",choices:["Les données personnelles.","Les déchets.","L’eau."],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."},{q:"Quel objectif exprime تقليل استهلاك الماء ?",choices:["Réduire la consommation d’eau.","Augmenter le nombre de publications.","Vendre des déchets."],answer:0,explain:"La réponse est explicitée dans le vocabulaire ou le cas de cette section."}],sectionOnly:!0}]},{id:"lng-it-comp",name:"Italien — Compréhension, expression et médiation",short:"Compréhension, expression et médiation",keywords:["Compréhension, expression et médiation","italien"],intro:"Deux textes originaux d’entraînement accompagnés d’une méthode, de questions corrigées et de pistes d’oral. Ils ne sont pas des documents authentiques ni des épreuves officielles. Lis d’abord le texte puis justifie tes réponses.",cours:[{h:"Comprendre un récit : un stage à Bologne",blocks:[{t:"p",c:"Texte original d’entraînement : Mi chiamo Giulia e studio economia a Bologna. L’estate scorsa ho fatto un tirocinio in una piccola libreria. La mattina aiutavo i clienti e preparavo gli ordini. Un giorno la responsabile mi ha chiesto di creare una pagina per il negozio. Ho proposto di pubblicare consigli di lettura, ma non fotografie dei clienti senza il loro consenso. Vorrei continuare a lavorare nel settore culturale."},{t:"p",c:"Commence par identifier qui parle, où et à quelle période. Ho fatto situe un événement accompli ; aiutavo et preparavo décrivent les tâches habituelles. Mais introduit une limite au projet numérique. Pour justifier une réponse, relève quelques mots pertinents puis reformule : Giulia desidera lavorare nella cultura. Ne traduis pas mot à mot tout le document."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Libreria","Librairie, et non bibliothèque."],["Consenso","Consentement."],["Vorrei","Je voudrais : projet souhaité."]]}]},{h:"Analyser un débat et préparer un oral",blocks:[{t:"p",c:"Texte original d’entraînement : Un’associazione di quartiere vuole aprire un laboratorio di riparazione. Secondo i volontari, riparare gli oggetti permette di ridurre i rifiuti e di trasmettere competenze. Alcuni abitanti sostengono il progetto, mentre altri temono il rumore. L’associazione propone quindi un’apertura limitata al pomeriggio e una riunione mensile con i residenti. Il progetto non è ancora stato approvato."},{t:"p",c:"Sépare le projet de son adoption effective. Repère les acteurs, leurs arguments et le compromis. Pour l’oral : présente le document comme un texte pédagogique, formule la question « Come conciliare ambiente e vita di quartiere? », expose deux positions, puis justifie ton avis. Pour une médiation en français, résume fidèlement le compromis sans ajouter de chiffres. En interaction, demande un éclaircissement : Può spiegare questo punto?"},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Riparazione","Réparation."],["Mentre","Tandis que ; met ici deux positions en contraste."],["Non ancora","Pas encore."]]}]}],games:[{id:"lng-it-comp-s1-qcm",type:"qcm",title:"Comprendre un récit : un stage à Bologne",icon:"❓",questions:[{q:"Où Giulia a-t-elle effectué son stage ?",choices:["Dans une librairie.","Dans une banque.","Dans une gare."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."},{q:"Quelle limite pose-t-elle à la publication des photos ?",choices:["Obtenir le consentement des clients.","Publier toutes les photos.","Abandonner toute présence numérique."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."},{q:"Que décrivent aiutavo et preparavo ?",choices:["Des tâches habituelles pendant le stage.","Un projet futur.","Une interdiction."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."}],sectionOnly:!0},{id:"lng-it-comp-s2-qcm",type:"qcm",title:"Analyser un débat et préparer un oral",icon:"❓",questions:[{q:"Quel est l’objectif annoncé du laboratoire ?",choices:["Réparer pour réduire les déchets et transmettre des compétences.","Vendre seulement des objets neufs.","Supprimer les réunions."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."},{q:"Quelle inquiétude certains habitants expriment-ils ?",choices:["Le bruit.","Le prix du train.","Le manque de livres."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."},{q:"Le projet est-il déjà approuvé ?",choices:["Non, pas encore.","Oui, définitivement.","Le texte ne mentionne aucun projet."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."}],sectionOnly:!0}]},{id:"lng-ar-comp",name:"Arabe — Compréhension, expression et médiation",short:"Compréhension, expression et médiation",keywords:["Compréhension, expression et médiation","arabe"],intro:"Deux textes originaux d’entraînement accompagnés d’une méthode, de questions corrigées et de pistes d’oral. Ils ne sont pas des documents authentiques ni des épreuves officielles. Lis d’abord le texte puis justifie tes réponses.",cours:[{h:"Comprendre un récit : un stage dans une librairie",blocks:[{t:"p",c:"Texte original d’entraînement en arabe standard : اسمي مريم وأدرس الاقتصاد. في الصيف الماضي، عملت في مكتبة تبيع الكتب في تونس. كنت أساعد الزبائن وأرتب الكتب. طلبت مني المديرة إعداد صفحة للمكتبة على الإنترنت. اقترحت نشر معلومات عن الكتب، لكنني رفضت نشر صور الزبائن دون موافقتهم. أريد العمل في المجال الثقافي."},{t:"p",c:"Maryam raconte une expérience passée dans une librairie à Tunis. Le mot مكتبة peut désigner une bibliothèque ou une librairie : تبيع الكتب (qui vend des livres) lève ici l’ambiguïté. Repère كنت أساعد : activité habituelle dans le passé. Pour comprendre le projet numérique, distingue l’action proposée et celle refusée. Cite le texte pour justifier, puis reformule sans inventer la durée exacte du stage."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["الزبائن","Les clients."],["موافقتهم","Leur accord / consentement."],["في الصيف الماضي","L’été dernier."]]}]},{h:"Analyser un projet et préparer un oral",blocks:[{t:"p",c:"Texte original d’entraînement en arabe standard : تريد جمعية محلية إنشاء ورشة لإصلاح الأجهزة. يقول المتطوعون إن الإصلاح يقلل النفايات ويساعد السكان على تعلم مهارات جديدة. يدعم بعض السكان المشروع، لكن آخرين يخافون من الضجيج. لذلك تقترح الجمعية فتح الورشة بعد الظهر فقط وتنظيم لقاء شهري مع السكان. لم توافق البلدية على المشروع بعد."},{t:"p",c:"Le document présente un projet d’atelier de réparation, ses avantages et une objection. الجمعية est l’association ; البلدية, la municipalité. لذلك relie l’inquiétude au compromis proposé. La dernière phrase indique une décision qui n’a pas encore été obtenue. Pour un oral, présente le support comme un texte pédagogique, expose les deux positions, puis formule ton avis avec في رأيي. Pour demander une clarification : هل يمكنك توضيح هذه الفكرة؟ (peux-tu expliquer cette idée ?)."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["ورشة","Atelier."],["الضجيج","Bruit."],["لم… بعد","Négation correspondant ici à pas encore."]]}]}],games:[{id:"lng-ar-comp-s1-qcm",type:"qcm",title:"Comprendre un récit : un stage dans une librairie",icon:"❓",questions:[{q:"Pourquoi مكتبة désigne-t-il ici une librairie ?",choices:["Le texte précise qu’elle vend des livres.","Le mot signifie toujours université.","La ville impose ce sens."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."},{q:"Que refuse Maryam ?",choices:["Publier des photos sans l’accord des clients.","Donner des informations sur les livres.","Travailler dans la culture."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."},{q:"À quelle période se déroule l’expérience racontée ?",choices:["L’été dernier.","L’année prochaine.","Le texte parle uniquement du présent."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."}],sectionOnly:!0},{id:"lng-ar-comp-s2-qcm",type:"qcm",title:"Analyser un projet et préparer un oral",icon:"❓",questions:[{q:"Quel est le projet de l’association ?",choices:["Un atelier de réparation des appareils.","Une nouvelle gare.","Une librairie en ligne."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."},{q:"Quelle inquiétude est mentionnée ?",choices:["Le bruit.","La fermeture de l’école.","Le prix du train."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."},{q:"La municipalité a-t-elle déjà donné son accord ?",choices:["Non, pas encore.","Oui, le texte le dit.","Aucune municipalité n’est mentionnée."],answer:0,explain:"Cette information se trouve dans le texte et son commentaire méthodologique."}],sectionOnly:!0}]},{id:"lng-it-culture-terminale",name:"Italien — Terminale · axes culturels",short:"Terminale · axes culturels",keywords:["Terminale · axes culturels","italien"],intro:"Repères du programme de Terminale, applicable depuis la rentrée 2026. Ces fiches proposent des points de départ et des phrases d’analyse, à compléter avec les documents authentiques étudiés en classe. En voie technologique, au moins trois axes sont étudiés dans l’année ; le sixième est recommandé. Ce ne sont pas des fiches de spécialité LLCER.",cours:[{h:"Axe 1 — Espace privé et espace public",blocks:[{t:"p",c:"La place, la piazza, est un espace public majeur dans de nombreuses villes italiennes, mais son usage dépend des habitants, des commerces, des touristes et des règles municipales. Un espace ouvert peut aussi exclure certains usages. La frontière entre privé et public se déplace également quand une expérience intime est publiée en ligne."},{t:"p",c:"Una piazza è uno spazio condiviso, ma gli usi possono entrare in conflitto. Une place est un espace partagé, mais ses usages peuvent entrer en conflit. Analyse qui peut entrer, qui décide et qui tire un avantage de la transformation d’un lieu."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : spazio condiviso : Espace partagé.; commercio : Commerce."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["piazza","Place publique."],["spazio condiviso","Espace partagé."],["commercio","Commerce."]]}]},{h:"Axe 2 — Territoire et mémoire",blocks:[{t:"p",c:"Un monument ou un lieu de mémoire sélectionne des événements et propose une façon de les raconter. Dans un document italien consacré à la Résistance, distingue l’événement historique, sa commémoration ultérieure et les usages actuels du souvenir. Une mémoire n’est pas une photographie neutre et exhaustive du passé."},{t:"p",c:"Un luogo della memoria invita a ricordare e a interrogare il passato. Un lieu de mémoire invite à se souvenir et à interroger le passé. Pour commenter une plaque, repère la date commémorée, la date de pose et le groupe qui prend la parole."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : targa : Plaque, notamment commémorative.; commemorazione : Commémoration."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["memoria","Mémoire."],["targa","Plaque, notamment commémorative."],["commemorazione","Commémoration."]]}]},{h:"Axe 3 — Fictions et réalités",blocks:[{t:"p",c:"Le cinéma et le roman peuvent s’inspirer de faits sociaux sans constituer un reportage. Le néoréalisme italien de l’après-guerre met notamment en scène des difficultés de la vie quotidienne. Même quand une œuvre semble proche du réel, cadrage, montage, personnages et narration construisent un point de vue."},{t:"p",c:"Un film può mostrare una realtà sociale senza essere un documentario. Un film peut montrer une réalité sociale sans être un documentaire. Sépare le personnage de l’acteur et le narrateur de l’auteur ; justifie une interprétation par une scène précise."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : personaggio : Personnage.; montaggio : Montage cinématographique."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["punto di vista","Point de vue."],["personaggio","Personnage."],["montaggio","Montage cinématographique."]]}]},{h:"Axe 4 — Enjeux et formes de la communication",blocks:[{t:"p",c:"Un message n’a pas le même effet selon qu’il paraît dans un journal, une publicité ou un réseau social. Pour un document italien, repère l’émetteur, le destinataire, le support et la visée : informer, convaincre, vendre ou divertir. Un slogan cherche souvent la mémorisation plutôt que la démonstration."},{t:"p",c:"Prima di condividere una notizia, bisogna verificarne la fonte. Avant de partager une information, il faut en vérifier la source. Compare un titre au contenu de l’article et demande-toi quelles informations ont été omises ; la popularité n’est pas une preuve."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : destinatario : Destinataire.; notizia : Nouvelle / information."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["fonte","Source."],["destinatario","Destinataire."],["notizia","Nouvelle / information."]]}]},{h:"Axe 5 — Citoyenneté et mondes virtuels",blocks:[{t:"p",c:"Participer à un débat numérique peut faciliter l’expression citoyenne, mais impose de protéger les personnes et de distinguer critique et harcèlement. Un cas italien de mobilisation en ligne doit être étudié à partir d’acteurs et d’actions identifiables, sans supposer que chaque partage conduit à une action sur le terrain."},{t:"p",c:"Essere cittadini online significa avere diritti e responsabilità. Être citoyen en ligne signifie avoir des droits et des responsabilités. Avant de publier une photo ou un témoignage, réfléchis à la vie privée, au consentement et aux conséquences d’une diffusion durable."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : consenso : Consentement.; molestie : Harcèlement / comportements importuns, selon le contexte."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["responsabilità","Responsabilité."],["consenso","Consentement."],["molestie","Harcèlement / comportements importuns, selon le contexte."]]}]},{h:"Axe 6 — De la République à l’Europe",blocks:[{t:"p",c:"Le référendum de 1946 conduit l’Italie à devenir une république ; la Constitution entre en vigueur en 1948. L’Italie figure parmi les six États signataires des traités de Rome de 1957, une étape de la construction européenne. Ne confonds pas ces communautés initiales avec l’Union européenne sous sa forme actuelle."},{t:"p",c:"La cittadinanza si esercita a livello nazionale ed europeo. La citoyenneté s’exerce à l’échelle nationale et européenne. Compare les niveaux de décision dans un exemple précis : une institution nationale et une institution européenne ne disposent pas automatiquement des mêmes compétences."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : Costituzione : Constitution.; trattato : Traité."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["Repubblica","République."],["Costituzione","Constitution."],["trattato","Traité."]]}]}],games:[{id:"lng-it-culture-terminale-s1-qcm",type:"qcm",title:"Axe 1 — Espace privé et espace public",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « piazza » ?",choices:["Place publique.","Espace partagé.","Commerce."],answer:0,explain:"Le vocabulaire de cette fiche définit piazza : Place publique."},{q:"Pourquoi une place publique peut-elle faire débat ?",choices:["Ses usages peuvent opposer différents acteurs.","Tous ses usagers ont nécessairement le même intérêt.","Un espace ouvert n’a aucune règle."],answer:0,explain:"La place, la piazza, est un espace public majeur dans de nombreuses villes italiennes, mais son usage dépend des habitants, des commerces, des touristes et des règles municipales. Un espace ouvert peut aussi exclure certains usages. La frontière entre privé et public se déplace également quand une expérience intime est publiée en ligne."}],sectionOnly:!0},{id:"lng-it-culture-terminale-s2-qcm",type:"qcm",title:"Axe 2 — Territoire et mémoire",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « memoria » ?",choices:["Mémoire.","Plaque, notamment commémorative.","Commémoration."],answer:0,explain:"Le vocabulaire de cette fiche définit memoria : Mémoire."},{q:"Quelles dates distinguer sur une plaque commémorative ?",choices:["L’événement et la pose de la plaque.","Une seule date sans contexte.","Seulement l’année de lecture de la plaque."],answer:0,explain:"Un monument ou un lieu de mémoire sélectionne des événements et propose une façon de les raconter. Dans un document italien consacré à la Résistance, distingue l’événement historique, sa commémoration ultérieure et les usages actuels du souvenir. Une mémoire n’est pas une photographie neutre et exhaustive du passé."}],sectionOnly:!0},{id:"lng-it-culture-terminale-s3-qcm",type:"qcm",title:"Axe 3 — Fictions et réalités",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « punto di vista » ?",choices:["Point de vue.","Personnage.","Montage cinématographique."],answer:0,explain:"Le vocabulaire de cette fiche définit punto di vista : Point de vue."},{q:"Un film néoréaliste est-il automatiquement un documentaire ?",choices:["Non, sa narration construit un point de vue.","Oui, s’il montre une rue.","Oui, si ses personnages ont des problèmes quotidiens."],answer:0,explain:"Le cinéma et le roman peuvent s’inspirer de faits sociaux sans constituer un reportage. Le néoréalisme italien de l’après-guerre met notamment en scène des difficultés de la vie quotidienne. Même quand une œuvre semble proche du réel, cadrage, montage, personnages et narration construisent un point de vue."}],sectionOnly:!0},{id:"lng-it-culture-terminale-s4-qcm",type:"qcm",title:"Axe 4 — Enjeux et formes de la communication",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « fonte » ?",choices:["Source.","Destinataire.","Nouvelle / information."],answer:0,explain:"Le vocabulaire de cette fiche définit fonte : Source."},{q:"Comment évaluer un titre de presse ?",choices:["Le confronter au contenu et aux sources de l’article.","Le croire dès qu’il est partagé.","Le traiter toujours comme une démonstration complète."],answer:0,explain:"Un message n’a pas le même effet selon qu’il paraît dans un journal, une publicité ou un réseau social. Pour un document italien, repère l’émetteur, le destinataire, le support et la visée : informer, convaincre, vendre ou divertir. Un slogan cherche souvent la mémorisation plutôt que la démonstration."}],sectionOnly:!0},{id:"lng-it-culture-terminale-s5-qcm",type:"qcm",title:"Axe 5 — Citoyenneté et mondes virtuels",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « responsabilità » ?",choices:["Responsabilité.","Consentement.","Harcèlement / comportements importuns, selon le contexte."],answer:0,explain:"Le vocabulaire de cette fiche définit responsabilità : Responsabilité."},{q:"Que faut-il examiner avant de publier un témoignage ?",choices:["La vie privée, le consentement et la diffusion durable.","Seulement le nombre de partages attendu.","Le principe que tout partage garantit une action réelle."],answer:0,explain:"Participer à un débat numérique peut faciliter l’expression citoyenne, mais impose de protéger les personnes et de distinguer critique et harcèlement. Un cas italien de mobilisation en ligne doit être étudié à partir d’acteurs et d’actions identifiables, sans supposer que chaque partage conduit à une action sur le terrain."}],sectionOnly:!0},{id:"lng-it-culture-terminale-s6-qcm",type:"qcm",title:"Axe 6 — De la République à l’Europe",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « Repubblica » ?",choices:["République.","Constitution.","Traité."],answer:0,explain:"Le vocabulaire de cette fiche définit Repubblica : République."},{q:"Quelle chronologie correspond à la fiche ?",choices:["République en 1946, Constitution en 1948, traités de Rome en 1957.","Constitution en 1946, République en 1957, traités en 1948.","Union européenne actuelle créée telle quelle en 1946."],answer:0,explain:"Le référendum de 1946 conduit l’Italie à devenir une république ; la Constitution entre en vigueur en 1948. L’Italie figure parmi les six États signataires des traités de Rome de 1957, une étape de la construction européenne. Ne confonds pas ces communautés initiales avec l’Union européenne sous sa forme actuelle."}],sectionOnly:!0}]},{id:"lng-ar-culture-terminale",name:"Arabe — Terminale · axes culturels",short:"Terminale · axes culturels",keywords:["Terminale · axes culturels","arabe"],intro:"Repères du programme de Terminale, applicable depuis la rentrée 2026. Ces fiches proposent des points de départ et des phrases d’analyse, à compléter avec les documents authentiques étudiés en classe. En voie technologique, au moins trois axes sont étudiés dans l’année ; le sixième est recommandé. Ce ne sont pas des fiches de spécialité LLCER.",cours:[{h:"Axe 1 — Espace privé et espace public",blocks:[{t:"p",c:"Un logement, une rue ou un café ne donne pas les mêmes possibilités de parole et de rencontre. Dans une ville du monde arabe, l’étude d’un lieu public doit tenir compte du quartier, des usages et des personnes présentes. La diffusion d’images d’un espace privé peut aussi changer la frontière entre intime et public."},{t:"p",c:"ليس كل ما يمكن نشره مناسبا للنشر. Tout ce qui peut être publié n’est pas nécessairement approprié à la publication. Pour analyser un document, identifie le lieu, les règles d’accès et les effets de l’exposition publique sur les personnes."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : الحياة الخاصة : La vie privée.; النشر : La publication / la diffusion."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["الفضاء العام","L’espace public."],["الحياة الخاصة","La vie privée."],["النشر","La publication / la diffusion."]]}]},{h:"Axe 2 — Territoire et mémoire",blocks:[{t:"p",c:"Un territoire peut porter plusieurs mémoires, transmises par les familles, les noms de rues, les bâtiments ou les archives. Dans un document du monde arabe, distingue la période évoquée du moment où le récit est produit. Des souvenirs différents ne se départagent pas par le seul nombre de personnes qui les répètent."},{t:"p",c:"تساعدنا الذاكرة على فهم علاقتنا بالمكان. La mémoire nous aide à comprendre notre relation au lieu. Compare deux récits en repérant leur auteur, leur date et leurs silences ; un témoignage est une source située, qu’il faut croiser avec d’autres documents."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : الشهادة : Le témoignage, dans le contexte de cette fiche.; الأرشيف : Les archives."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["الذاكرة","La mémoire."],["الشهادة","Le témoignage, dans le contexte de cette fiche."],["الأرشيف","Les archives."]]}]},{h:"Axe 3 — Fictions et réalités",blocks:[{t:"p",c:"Un roman, un conte ou un film peut rendre visible une réalité sociale tout en inventant ses personnages et son intrigue. La fiction n’est pas une fausse information : elle se présente dans un cadre artistique. À l’inverse, une fabrication diffusée comme un fait réel trompe sur son statut."},{t:"p",c:"قد تكشف الرواية حقيقة اجتماعية بشخصيات خيالية. Le roman peut révéler une réalité sociale à travers des personnages fictifs. Distingue l’auteur, le narrateur et le personnage ; interprète une scène à partir d’indices précis sans prendre tous ses détails pour des archives."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : الشخصية : Le personnage, dans un récit.; الخيال : L’imagination / la fiction."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["الرواية","Le roman."],["الشخصية","Le personnage, dans un récit."],["الخيال","L’imagination / la fiction."]]}]},{h:"Axe 4 — Enjeux et formes de la communication",blocks:[{t:"p",c:"L’arabe standard est fréquent dans l’information écrite et dans de nombreuses situations formelles ; les usages dialectaux varient selon les lieux, les supports et les destinataires. Un choix de langue peut produire proximité ou distance, mais ne permet pas à lui seul de juger la fiabilité d’un message."},{t:"p",c:"تختلف طريقة التعبير بحسب الجمهور ووسيلة التواصل. La manière de s’exprimer varie selon le public et le moyen de communication. Pour analyser un message, identifie émetteur, public, support et objectif. Sépare information, opinion et publicité ; cite un indice pour justifier chaque distinction."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : وسيلة التواصل : Le moyen de communication.; الإعلان : La publicité / l’annonce."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["الجمهور","Le public."],["وسيلة التواصل","Le moyen de communication."],["الإعلان","La publicité / l’annonce."]]}]},{h:"Axe 5 — Citoyenneté et mondes virtuels",blocks:[{t:"p",c:"Les espaces numériques peuvent donner de la visibilité à une initiative citoyenne tout en exposant les personnes à la surveillance, au harcèlement ou à la désinformation. Étudie un cas situé plutôt que de parler de pratiques identiques dans tous les pays arabes. La liberté d’expression ne dispense pas de vérifier les faits et de respecter les personnes."},{t:"p",c:"قبل مشاركة خبر، تحقق من مصدره وتاريخه. Avant de partager une information, vérifie sa source et sa date. Pour une image, recherche aussi son contexte : une photographie authentique peut être trompeuse si elle est attribuée au mauvais événement."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : المصدر : La source.; التحقق : La vérification."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["المواطنة","La citoyenneté."],["المصدر","La source."],["التحقق","La vérification."]]}]},{h:"Axe 6 — Focale Égypte et Liban : arts et histoire",blocks:[{t:"p",c:"La focale de Terminale concerne l’Égypte et le Liban, en reliant création artistique et histoire. Naguib Mahfouz, écrivain égyptien, situe une partie de son œuvre au Caire ; la chanteuse libanaise Fairouz permet d’aborder les liens entre chanson, attachement à un lieu et mémoire collective. Ces deux trajectoires ne résument pas les scènes artistiques de leurs pays."},{t:"p",c:"يرتبط الأدب والفن بالتاريخ دون أن يكونا نسخة منه. La littérature et l’art sont liés à l’histoire sans en être une copie. Pour étudier un extrait, précise œuvre, auteur, date et contexte. Une chanson ou un roman se commente comme une création, pas comme un relevé exhaustif des événements."},{t:"p",c:"Pour t’entraîner, résume le problème en deux phrases dans la langue étudiée, donne un exemple précis tiré d’un document et formule une limite. Relis les accords et les connecteurs. Cette production ouverte est un entraînement personnel : elle n’est pas notée automatiquement par le QCM."},{t:"p",c:"Repères lexicaux de cet axe : التاريخ : L’histoire.; الأغنية : La chanson."},{t:"table",h:"Notions et définitions",head:["Notion","Définition"],rows:[["الأدب","La littérature."],["التاريخ","L’histoire."],["الأغنية","La chanson."]]}]}],games:[{id:"lng-ar-culture-terminale-s1-qcm",type:"qcm",title:"Axe 1 — Espace privé et espace public",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « الفضاء العام » ?",choices:["L’espace public.","La vie privée.","La publication / la diffusion."],answer:0,explain:"Le vocabulaire de cette fiche définit الفضاء العام : L’espace public."},{q:"Que peut changer la publication d’une image privée ?",choices:["La frontière entre intimité et exposition publique.","Elle garantit le consentement de tous.","Elle supprime tous les effets sur les personnes."],answer:0,explain:"Un logement, une rue ou un café ne donne pas les mêmes possibilités de parole et de rencontre. Dans une ville du monde arabe, l’étude d’un lieu public doit tenir compte du quartier, des usages et des personnes présentes. La diffusion d’images d’un espace privé peut aussi changer la frontière entre intime et public."}],sectionOnly:!0},{id:"lng-ar-culture-terminale-s2-qcm",type:"qcm",title:"Axe 2 — Territoire et mémoire",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « الذاكرة » ?",choices:["La mémoire.","Le témoignage, dans le contexte de cette fiche.","Les archives."],answer:0,explain:"Le vocabulaire de cette fiche définit الذاكرة : La mémoire."},{q:"Comment utiliser un témoignage de mémoire ?",choices:["Le situer et le croiser avec d’autres sources.","Le déclarer exhaustif.","Le croire uniquement parce qu’il est souvent répété."],answer:0,explain:"Un territoire peut porter plusieurs mémoires, transmises par les familles, les noms de rues, les bâtiments ou les archives. Dans un document du monde arabe, distingue la période évoquée du moment où le récit est produit. Des souvenirs différents ne se départagent pas par le seul nombre de personnes qui les répètent."}],sectionOnly:!0},{id:"lng-ar-culture-terminale-s3-qcm",type:"qcm",title:"Axe 3 — Fictions et réalités",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « الرواية » ?",choices:["Le roman.","Le personnage, dans un récit.","L’imagination / la fiction."],answer:0,explain:"Le vocabulaire de cette fiche définit الرواية : Le roman."},{q:"Pourquoi une fiction n’est-elle pas une fausse information ?",choices:["Elle se présente dans un cadre artistique.","Tous ses détails sont des archives.","Le narrateur est toujours son auteur réel."],answer:0,explain:"Un roman, un conte ou un film peut rendre visible une réalité sociale tout en inventant ses personnages et son intrigue. La fiction n’est pas une fausse information : elle se présente dans un cadre artistique. À l’inverse, une fabrication diffusée comme un fait réel trompe sur son statut."}],sectionOnly:!0},{id:"lng-ar-culture-terminale-s4-qcm",type:"qcm",title:"Axe 4 — Enjeux et formes de la communication",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « الجمهور » ?",choices:["Le public.","Le moyen de communication.","La publicité / l’annonce."],answer:0,explain:"Le vocabulaire de cette fiche définit الجمهور : Le public."},{q:"Le choix de l’arabe standard suffit-il à prouver la fiabilité ?",choices:["Non, il faut aussi examiner les sources et les preuves.","Oui, quel que soit le message.","Oui, s’il s’agit d’une publicité."],answer:0,explain:"L’arabe standard est fréquent dans l’information écrite et dans de nombreuses situations formelles ; les usages dialectaux varient selon les lieux, les supports et les destinataires. Un choix de langue peut produire proximité ou distance, mais ne permet pas à lui seul de juger la fiabilité d’un message."}],sectionOnly:!0},{id:"lng-ar-culture-terminale-s5-qcm",type:"qcm",title:"Axe 5 — Citoyenneté et mondes virtuels",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « المواطنة » ?",choices:["La citoyenneté.","La source.","La vérification."],answer:0,explain:"Le vocabulaire de cette fiche définit المواطنة : La citoyenneté."},{q:"Comment une photographie authentique peut-elle tromper ?",choices:["Si elle est attribuée au mauvais événement.","Elle ne peut jamais tromper.","Sa date ne compte jamais."],answer:0,explain:"Les espaces numériques peuvent donner de la visibilité à une initiative citoyenne tout en exposant les personnes à la surveillance, au harcèlement ou à la désinformation. Étudie un cas situé plutôt que de parler de pratiques identiques dans tous les pays arabes. La liberté d’expression ne dispense pas de vérifier les faits et de respecter les personnes."}],sectionOnly:!0},{id:"lng-ar-culture-terminale-s6-qcm",type:"qcm",title:"Axe 6 — Focale Égypte et Liban : arts et histoire",icon:"❓",questions:[{q:"Dans cette fiche, que signifie « الأدب » ?",choices:["La littérature.","L’histoire.","La chanson."],answer:0,explain:"Le vocabulaire de cette fiche définit الأدب : La littérature."},{q:"Quel rapprochement correspond à la fiche ?",choices:["Mahfouz et le Caire ; Fairouz et la chanson libanaise.","Mahfouz et la chanson libanaise ; Fairouz et le roman cairote.","Deux trajectoires résumant intégralement tous les arts des deux pays."],answer:0,explain:"La focale de Terminale concerne l’Égypte et le Liban, en reliant création artistique et histoire. Naguib Mahfouz, écrivain égyptien, situe une partie de son œuvre au Caire ; la chanteuse libanaise Fairouz permet d’aborder les liens entre chanson, attachement à un lieu et mémoire collective. Ces deux trajectoires ne résument pas les scènes artistiques de leurs pays."}],sectionOnly:!0}]}],c={id:e,name:i,short:a,icon:n,color:t,tagline:r,chapters:o},h=Object.freeze(Object.defineProperty({__proto__:null,chapters:o,color:t,default:c,icon:n,id:e,name:i,short:a,tagline:r},Symbol.toStringTag,{value:"Module"}));export{m as a,p as d,d as e,h as m};
